/* Bonsai species care library. USDA landscape zones and practical pot-winter notes are conservative ranges; cultivars and local weather vary. */
const SPECIES=[{"id":"acer-palmatum","common":"Japanese maple","scientific":"Acer palmatum","synonyms":[],"aliases":["momiji","Japanese maple"],"family":"Sapindaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Many cultivars are happiest in zones 6–8. Some delicate dissectum types are less hardy, especially in pots. Landscape trees in zone 5 often need a sheltered site.","rootMinF":15,"protectBelowF":25,"bringInBelowF":null,"potNote":"In a shallow pot, treat as about 1–2 zones less hardy than a landscape tree. Roots are commonly injured around 15–20°F (−9 to −7°C), sometimes sooner in a very small pot.","dormancy":"Requires a genuine winter rest of several weeks, generally near 32–45°F (0–7°C). Do not overwinter in a warm living room — the tree will not rest properly and spring growth is often weak.","winterizing":["Let the tree harden outdoors through autumn; do not rush it into a warm space when leaves color.","Before nights regularly drop into the mid-20s°F (around −4°C), insulate the pot: mulch it, plunge it to the rim in the ground, wrap it, or move it to a cold frame.","An unheated garage or shed that stays mostly in the 25–45°F range works if the tree is fully dormant. Deciduous maples can sit in low light while leafless, but keep them cold.","Shelter from drying wind and from rapid freeze–thaw of the root ball.","In early spring, return the tree to light as buds swell, but protect new leaves from a late frost."],"wateringWinter":"Water sparingly, just enough that the root ball never dries out completely. Check on milder days. Standing wet plus hard freeze is rough on roots — good drainage still matters in winter.","lightWinter":"While leafless and cold, light is secondary. Once buds swell, give good light and keep the tree from a warm, dark corner.","repotWhen":"Late winter to early spring","repotCue":"When buds swell and show color, but before they break into leaf — or at the very first hint of opening","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 3–5 years when mature, or when roots have packed the pot","repotNotes":"Use a well-draining deciduous mix (for example akadama, pumice, and lava). Avoid a heavy, wet soil. Do not repot in autumn in the North; the tree should not go into winter with a reduced root system. Wait until late spring in very cold zones if the ground is still frozen.","rootPruning":"Done at repotting. Trim back long circling roots and keep a radial nebari. Do not remove more than about one-third to one-half of the root mass on a healthy tree; be more conservative on a weak tree. Fine roots regenerate well in spring.","structuralPruning":"Best after you can see the structure — mid-summer on a healthy tree, or after leaf-drop in autumn. Hard cuts in late winter can bleed sap; if you prune then, expect some bleeding and keep cuts clean. Never strip a weak tree.","pinching":"During the growing season, pinch or cut extending shoots after one or two pairs of leaves on the outer canopy, leaving a bit more strength on weaker inner branches. Partial defoliation is only for vigorous trees in mid-summer, and never in a drought.","wiring":"After leaf-drop or in mid-summer when leaves are smaller. Branches are a bit brittle — wrap with raffia on older wood if you need a strong bend, and check wires before late-spring thickening.","fertilizing":"Begin 3–4 weeks after a spring flush or after repotting, and feed regularly through mid-summer. Switch to a lower-nitrogen or stop feeding by late summer so the tree hardens. Do not fertilize a dormant or newly repotted tree.","pests":"Aphids on new growth, scale, caterpillars, verticillium wilt (avoid wounding roots in infected soil), and leaf scorch from hot, dry wind or midday sun. Poor drainage leads to root decline.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"palmate","lobes":"5-9","margin":"serrate","shape":"Palmate, usually 5–9 deeply cut, tapering lobes","evergreen":false,"features":"Opposite pairs on the stem; long petioles, often red or green; palmate veins meeting at the leaf base. Cultivars range from broad lobes to finely dissected 'laceleaf' forms."},"facts":["In Japan it is often called momiji, and autumn viewing of maples is a tradition as loved as cherry blossom season.","There are well over a thousand named cultivars, from tiny dwarf shrublets to upright trees with deeply cut red or green leaves.","Maples bleed sap if cut hard in late winter; many growers prefer to do major pruning after the spring flush or in summer."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Prime repotting and root-pruning month in much of the U.S., as buds swell but before they open. Protect swelling buds and new leaves from a late frost.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"On a healthy, vigorous tree, partial defoliation or leaf trimming can be done in early to mid-summer to tighten internodes and let light in. Never defoliate a weak tree.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Famous autumn color — red, orange, or gold depending on the cultivar. After leaves fall, study the ramification and adjust wire.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"acer-buergerianum","common":"Trident maple","scientific":"Acer buergerianum","synonyms":[],"aliases":["trident maple","three-toothed maple"],"family":"Sapindaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"9","zoneNote":"Generally a little more heat-tolerant than Japanese maple, and widely grown in zones 5–9. Some trees in zone 5 appreciate a sheltered winter site.","rootMinF":15,"protectBelowF":25,"bringInBelowF":null,"potNote":"In a pot, protect the roots once nights settle in the mid-20s°F. Root injury is often reported around 15–20°F in shallow containers.","dormancy":"Needs a cold winter rest, similar to Japanese maple. Do not keep it in a heated house all winter.","winterizing":["Harden the tree outdoors in autumn.","Insulate or plunge the pot, or use a cold frame, before regular nights in the mid-20s°F.","An unheated garage in the mid-20s to 40s°F is acceptable once the tree is leafless and dormant.","Keep the root ball from cycling through hard freezes and thaws, and from drying out."],"wateringWinter":"Sparse watering; never bone-dry, never waterlogged and frozen.","lightWinter":"Low light is tolerable while leafless and cold. Return to good light as buds swell.","repotWhen":"Late winter to early spring","repotCue":"When buds swell, just before they break","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young (tridents grow quickly); every 2–4 years when mature","repotNotes":"Trident maples often build a strong nebari and recover from root pruning very well in spring. A free-draining deciduous mix is best. They tolerate slightly more root reduction than Japanese maple when healthy.","rootPruning":"At repotting. They readily form surface roots and are a classic choice for root-over-rock. Be reasonably bold on a vigorous tree, conservative on a weak one.","structuralPruning":"After leaf-drop or in mid-summer. Like other maples, late-winter cuts may bleed. Fast growth means wires bite quickly.","pinching":"Pinch or shorten shoots during the growing season to keep internodes short. They back-bud readily. Partial defoliation is possible on strong trees in mid-summer.","wiring":"Autumn after leaf-drop, or mid-summer. Check wires often — this species thickens fast.","fertilizing":"Feed regularly from late spring through mid-summer once growth is underway; taper or stop by late summer. Skip fertilizer right after repotting.","pests":"Aphids, scale, caterpillars, and chlorosis in very alkaline water or soil. Can scorch in intense, dry heat if kept too dry.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"trifoliate","lobes":"3","margin":"serrate","shape":"Three-lobed, like a trident or duck’s foot; lobes are relatively stiff and often slightly glossy","evergreen":false,"features":"Opposite arrangement; three forward-pointing lobes (sometimes a small extra tooth). Leaves are typically smaller and more leathery than Japanese maple. Fall color is often orange, red, or scarlet."},"facts":["The three-lobed leaf is the easy field mark — it looks like a small trident.","A favorite for root-over-rock compositions because it throws strong, adaptive roots.","In the ground it can become a sizable shade tree; in a pot it ramifies well and reduces leaf size with consistent pruning."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Best repotting and root-pruning window, as buds swell. Tridents often push early — don’t miss the cue.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Very vigorous spring growth. Pinch early so the internodes stay short.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Reliable, often brilliant, fall color. After leaf-drop, wire and plan any structural work.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"ulmus-parvifolia","common":"Chinese elm","scientific":"Ulmus parvifolia","synonyms":[],"aliases":["lacebark elm","Chinese elm"],"family":"Ulmaceae","place":"both","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"Often listed as zones 6–9, sometimes 5b–10. In warm-winter areas it may be nearly evergreen; in colder zones it is deciduous. Hardiness of individual trees varies, and potted trees are less hardy than those in the ground.","rootMinF":20,"protectBelowF":28,"bringInBelowF":null,"potNote":"In a pot, be conservative: many growers protect below the upper 20s°F, and root damage becomes likely in the high teens to around 20°F. Do not treat a potted Chinese elm as a zone 5 tree.","dormancy":"Benefits from a cool winter rest. In cold climates it will drop leaves and rest. It can be grown as an indoor/outdoor tree, but winter in a consistently warm, dim room leads to weak growth. A cool, bright rest is better than a hot house if you bring it in.","winterizing":["In zones 8–9, many potted trees can stay outside with pot protection from the occasional freeze.","In zones 6–7, insulate the pot, use a cold frame, or overwinter in an unheated or lightly heated space that stays mostly above the high teens, ideally in the 30–50°F range.","If you must bring it into the house, give the brightest, coolest window you can and expect some leaf drop.","Do not let the root ball freeze hard in a small pot."],"wateringWinter":"Reduced, but never bone-dry. Evergreen or half-leaved trees in mild climates still transpire and need more water than fully leafless ones.","lightWinter":"Good light if the tree holds leaves. Leafless dormant trees can take lower light if they stay cold.","repotWhen":"Late winter to early spring (or, in warm climates, when growth is just starting)","repotCue":"As buds swell, or just as new leaves begin in mild-winter areas","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature — this is a fast rooter","repotNotes":"Tolerates fairly ambitious root work in spring when healthy. A standard well-draining mix is fine. In frost-free climates, late spring is also workable.","rootPruning":"At repotting. Recovers well. Keep a radial root spread; they often produce a fine, dense root system.","structuralPruning":"Almost year-round on a healthy tree, with the heaviest cuts in late winter or after a flush. It back-buds freely, which is why it is such a good beginner tree.","pinching":"Pinch or clip new shoots hard during the growing season to build fine ramification. It can be pruned often.","wiring":"Spring or autumn; the wood is flexible when young. Check wires — growth is fast.","fertilizing":"Feed regularly through the growing season; taper in late summer if the tree will face a real winter. Indoor trees under lights can take a lighter winter feed if they keep growing.","pests":"Scale, spider mites (especially indoors or in dry heat), aphids, and elm leaf beetle in some regions. Generally tougher than many maples.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Small, ovate to elliptic, slightly unequal at the base","evergreen":false,"features":"Alternate leaves, often ½–2 inches long on bonsai, with single or double teeth and a slightly lopsided base. Bark on older trunks becomes mottled, flaking, and ‘lacebark’ in cream, gray, and orange-brown. May hold leaves all winter in mild climates."},"facts":["One of the most recommended first bonsai: forgiving, fine-twigged, and handsome in every season.","The mottled, flaking bark is a signature of older trees and is the reason it is also called lacebark elm.","It is not the same species as American elm (Ulmus americana) and is generally more resistant to Dutch elm disease, though not immune."],"calendar":{"1":"In cold climates, dormant and leafless — keep cold and barely moist. In mild climates it may still hold leaves; protect the pot from the odd freeze and give light.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Prime repotting season in most of the U.S. The tree recovers quickly if it is healthy and nights are no longer bitterly cold.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Clip-and-grow or pinch steadily. This is a good month to tighten ramification.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"If you are in a cold zone, protection should already be in place. In a mild zone, enjoy the semi-evergreen foliage and still watch for a sudden freeze.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"pinus-thunbergii","common":"Japanese black pine","scientific":"Pinus thunbergii","synonyms":["Pinus thunbergiana"],"aliases":["kuromatsu","Japanese black pine"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"8","zoneNote":"Typically listed as zones 6–8, sometimes 5b–8 with shelter. A coastal native of Japan; it dislikes severe inland cold and also hates poorly drained soil.","rootMinF":15,"protectBelowF":25,"bringInBelowF":null,"potNote":"Keep the tree outdoors for a real winter. Protect the pot below the mid-20s°F and shelter needles from drying wind. Roots in shallow pots can be hurt around 15–20°F.","dormancy":"Must have a cold winter rest outdoors or in a cold frame. A heated house will slowly weaken it.","winterizing":["Leave the tree outside or in a cold, bright frame.","Insulate the pot (mulch, plunge, wrap, or a cold frame) before hard, regular freezes.","Provide a windbreak; winter desiccation of needles is a common injury.","Do not move it into a warm indoor room."],"wateringWinter":"Evergreens still transpire. Water when the mix begins to dry, choosing milder days. Do not leave the pot bone-dry in a freeze, and do not leave it soggy.","lightWinter":"Full light. A dark garage is a poor long-term winter home for an evergreen pine.","repotWhen":"Early spring","repotCue":"As buds swell, before candles elongate strongly","repotMonths":[2,3,4],"repotFreq":"Every 2–3 years when young; every 3–5 years when mature, or when the mix has broken down","repotNotes":"Use a very free-draining, inorganic mix (akadama, pumice, lava, or similar grit). Keep some of the established mycorrhizal soil against the roots if the tree is healthy. Mid-summer repotting is practiced by some experienced growers in specific climates; spring is the conservative choice.","rootPruning":"At spring repotting. Pines should not lose as much root as a deciduous tree. Keep some old soil and mycorrhiza, and do not bareroot a pine unless you have a clear reason and experience.","structuralPruning":"Heavy branch cuts are often done in late summer to autumn, or planned around decandling, so wounds close well. Avoid large cuts in deep winter or during a soft spring push.","pinching":"Black pine is trained with candle pruning and, on a two-flush program, mid-summer decandling of strong candles so a second, shorter flush forms. Timing is local (often early to mid-June in much of the U.S.). Needle thinning follows on strong trees. Do not decandle a weak tree.","wiring":"Autumn through early spring, when the tree is less sappy and you are less likely to knock off candles. Pad older branches; pine wood can snap if rushed.","fertilizing":"Feed well in spring on strong, established trees. Reduce or pause around decandling, then resume when new buds are visible. Stop nitrogen by late summer so the tree hardens.","pests":"Aphids, adelgids, scale, pine sawfly, needle cast, and tip blight. Good sun and airflow prevent many needle diseases. Poor drainage is often fatal over time.","leaf":{"group":"needle","arrangement":"fascicle-2","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Needles in pairs (fascicles of 2), typically 3–5 inches, stiff, dark green, and slightly twisted","evergreen":true,"features":"Two needles per bundle, longer and stiffer than Japanese white pine. White sheaths at the base of new fascicles. Dark, fissured, almost blackish bark on older trunks — the source of the common name."},"facts":["A classic tree of Japanese gardens and bonsai, associated with longevity and the seashore.","It is often used as a rootstock for grafting Japanese white pine, whose own roots are more finicky.","The two-flush decandling method is a signature of black-pine training and is how growers build short, dense foliage pads."],"calendar":{"1":"Dormant. Keep the tree cold and protected from drying wind. Water when the root ball starts to dry — evergreens still transpire. No fertilizer.","2":"Late dormancy. In milder zones, prepare for early-spring repotting of trees that need it. Keep protection in place through the coldest nights.","3":"Preferred repotting window in most climates, as buds swell and before candles elongate strongly. Use a free-draining, grit-heavy mix. Wait several weeks before fertilizing a newly repotted tree.","4":"Candles extend. Begin a regular fertilizer program on established trees. Watch for sawfly and needle cast. Wiring is possible but buds are easy to knock off.","5":"Candle work begins in many climates: shorten or select candles according to the tree’s strength and style. Keep watering even. Full sun is usually preferred.","6":"Decandling month for many U.S. growers on a two-flush program. Timing depends on your summer — watch the tree, not only the calendar — and skip this on a weak tree.","7":"New shoots harden. Resume fertilizing after decandling once new buds are visible. Needle thinning can begin on strong trees. Avoid heavy root work in high heat.","8":"Continue light needle work if needed. Taper fertilizer late in the month. Watch for mites and summer drought stress.","9":"Stop nitrogen so the tree hardens. Autumn needle thinning is traditional on some pines. Check wires. Do not repot in the North.","10":"Good month for wiring while the tree is slowing and wood is less brittle than in deep winter. Reduce water slightly. Prepare winter wind protection.","11":"Set up winter protection: a cold frame, windbreak, or unheated space, and mulch or wrap the pot. Evergreen foliage must not sit in a warm, dark room.","12":"Check water on mild days. Sun and wind can desiccate foliage even in the cold. Keep the tree firmly dormant and cold."}},{"id":"pinus-parviflora","common":"Japanese white pine","scientific":"Pinus parviflora","synonyms":["Pinus pentaphylla"],"aliases":["five-needle pine","goyomatsu","Japanese white pine"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Typically zones 5–8. It prefers cooler summers than black pine and can struggle in hot, humid inland sites if the roots overheat or stay wet.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Slightly hardier than black pine in many lists, but a pot is still about 1–2 zones less forgiving. Protect roots in the low 20s°F and prevent winter windburn of the short needles.","dormancy":"Outdoor cold rest is required. Do not overwinter in a heated house.","winterizing":["Keep it outside or in a bright cold frame.","Insulate the pot before regular hard freezes, and block drying wind.","Avoid a warm indoor room.","In very snowy climates, a light snow cover on the pot can be helpful insulation if the tree still gets air and the foliage is not crushed for months."],"wateringWinter":"Water on mild days when the mix has started to dry. Short-needled white pines can still desiccate in winter wind.","lightWinter":"Full light and cold air.","repotWhen":"Early spring","repotCue":"As buds swell, before candles extend","repotMonths":[3,4],"repotFreq":"Every 3–5 years, or when the soil has broken down; young trees may need a slightly shorter cycle","repotNotes":"Very free-draining, gritty mix. Many collected or grafted trees are on black-pine rootstock — treat the roots with pine-level caution, keep some old mycorrhizal soil, and do not bareroot. White pine’s own roots are considered more sensitive than black pine’s.","rootPruning":"Conservative, at spring repotting. Leave more of the root mass than you would on a maple.","structuralPruning":"Late summer to autumn for larger cuts, when the tree can begin to close wounds. Avoid heavy cutting during the spring push.","pinching":"Usually a one-flush pine in bonsai practice: shorten candles in late spring, and thin needles to balance strength and let light into the pads. Do not use a harsh black-pine decandling program unless you know the tree will respond.","wiring":"Autumn through early spring. The shorter, tufted needles make wiring pads a little more delicate — protect the needles.","fertilizing":"Moderate. White pines are often fed a bit more lightly than black pines. Start after spring growth moves, taper by late summer. No winter feed.","pests":"Scale, adelgids, needle blight, and root decline from wet soil. Hot, stagnant air is a common problem in summer.","leaf":{"group":"needle","arrangement":"fascicle-5","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Needles in bundles of five, short (often 1½–2½ inches), slightly curved, and bluish- to gray-green","evergreen":true,"features":"Five needles per fascicle — the easy ID versus two-needle black or Scots pine. Needles form brush-like tufts at the tips. Bark is smoother and greyer than black pine when young."},"facts":["Called goyomatsu in Japan, it is among the most prized pines for bonsai, especially older, densely padded trees.","Many bonsai ‘white pines’ are grafted onto Japanese black pine roots, which are more vigorous and adaptable.","The five-needle bundles and short, silvery needles give it a softer, cloud-like silhouette compared with black pine."],"calendar":{"1":"Dormant. Keep the tree cold and protected from drying wind. Water when the root ball starts to dry — evergreens still transpire. No fertilizer.","2":"Late dormancy. In milder zones, prepare for early-spring repotting of trees that need it. Keep protection in place through the coldest nights.","3":"Preferred repotting window in most climates, as buds swell and before candles elongate strongly. Use a free-draining, grit-heavy mix. Wait several weeks before fertilizing a newly repotted tree.","4":"Candles extend. Begin a regular fertilizer program on established trees. Watch for sawfly and needle cast. Wiring is possible but buds are easy to knock off.","5":"Shorten candles according to the strength of each shoot, rather than a full black-pine decandling, unless you are following a program you know this tree accepts.","6":"Needle thinning and balancing of pads on strong trees. Avoid mid-summer root work.","7":"New shoots harden. Resume fertilizing after decandling once new buds are visible. Needle thinning can begin on strong trees. Avoid heavy root work in high heat.","8":"Continue light needle work if needed. Taper fertilizer late in the month. Watch for mites and summer drought stress.","9":"Stop nitrogen so the tree hardens. Autumn needle thinning is traditional on some pines. Check wires. Do not repot in the North.","10":"Good month for wiring while the tree is slowing and wood is less brittle than in deep winter. Reduce water slightly. Prepare winter wind protection.","11":"Set up winter protection: a cold frame, windbreak, or unheated space, and mulch or wrap the pot. Evergreen foliage must not sit in a warm, dark room.","12":"Check water on mild days. Sun and wind can desiccate foliage even in the cold. Keep the tree firmly dormant and cold."}},{"id":"pinus-sylvestris","common":"Scots pine","scientific":"Pinus sylvestris","synonyms":[],"aliases":["Scotch pine","Scots pine"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"2","zoneMax":"7","zoneNote":"One of the hardiest bonsai pines, generally zones 2–7. It dislikes hot, humid summers and is at its best in cool or cold-winter climates.","rootMinF":5,"protectBelowF":15,"bringInBelowF":null,"potNote":"The species is very cold-hardy in the ground, but a small pot can still freeze through. Insulate the pot in deep cold (around 10–15°F and below is a prudent trigger), and always stop winter wind from drying the needles.","dormancy":"Needs a real, cold winter. Do not bring it into a heated house.","winterizing":["Leave it outdoors or in a cold, bright frame.","Mulch or wrap the pot for severe cold, even though the species is hardy.","Wind protection matters as much as temperature.","Never overwinter it in a warm room."],"wateringWinter":"Water on mild days when the soil has started to dry. Evergreen needles still lose water in winter wind.","lightWinter":"Full light and cold conditions.","repotWhen":"Early spring","repotCue":"As buds swell, before candles elongate","repotMonths":[3,4],"repotFreq":"Every 2–4 years when young; every 3–5 years when mature","repotNotes":"Gritty, very free-draining pine mix. Keep some established soil/mycorrhiza. Spring is the conservative window.","rootPruning":"Moderate, at spring repotting. Do not bareroot a pine routinely.","structuralPruning":"Late summer to autumn for larger cuts. The naturally irregular, windswept habit suits informal and bunjin styles.","pinching":"Shorten candles in late spring according to strength. Needle thinning on strong trees in summer or early autumn. It is generally treated as a one-flush pine.","wiring":"Autumn through early spring. Older branches can be stiff; bend gradually.","fertilizing":"Regular in spring and early summer on established trees; taper by late summer. No winter fertilizer.","pests":"Sawfly, adelgids, scale, diplodia tip blight, and root problems from wet soil. Heat plus humidity is harder on this northern pine than cold is.","leaf":{"group":"needle","arrangement":"fascicle-2","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Needles in pairs, usually 1½–3 inches, blue-green, twisted","evergreen":true,"features":"Two twisted blue-green needles per fascicle, shorter than typical black-pine needles. Upper trunk and branches often show distinctive orange to reddish-brown flaking bark."},"facts":["The orange bark on the upper trunk is a trademark and is often featured in bonsai.","It has the widest natural distribution of any pine, from Scotland across Eurasia, which is why it handles cold so well.","In bonsai it often looks best with a slightly wild, windswept or informal outline rather than tight formal pads."],"calendar":{"1":"Dormant. Keep the tree cold and protected from drying wind. Water when the root ball starts to dry — evergreens still transpire. No fertilizer.","2":"Late dormancy. In milder zones, prepare for early-spring repotting of trees that need it. Keep protection in place through the coldest nights.","3":"Preferred repotting window in most climates, as buds swell and before candles elongate strongly. Use a free-draining, grit-heavy mix. Wait several weeks before fertilizing a newly repotted tree.","4":"Candles extend. Begin a regular fertilizer program on established trees. Watch for sawfly and needle cast. Wiring is possible but buds are easy to knock off.","5":"Candle work begins in many climates: shorten or select candles according to the tree’s strength and style. Keep watering even. Full sun is usually preferred.","6":"Usually a candle-shortening and needle-balancing month rather than full decandling. Avoid heat stress in warm regions.","7":"New shoots harden. Resume fertilizing after decandling once new buds are visible. Needle thinning can begin on strong trees. Avoid heavy root work in high heat.","8":"Continue light needle work if needed. Taper fertilizer late in the month. Watch for mites and summer drought stress.","9":"Stop nitrogen so the tree hardens. Autumn needle thinning is traditional on some pines. Check wires. Do not repot in the North.","10":"Good month for wiring while the tree is slowing and wood is less brittle than in deep winter. Reduce water slightly. Prepare winter wind protection.","11":"Set up winter protection: a cold frame, windbreak, or unheated space, and mulch or wrap the pot. Evergreen foliage must not sit in a warm, dark room.","12":"Check water on mild days. Sun and wind can desiccate foliage even in the cold. Keep the tree firmly dormant and cold."}},{"id":"pinus-mugo","common":"Mugo pine","scientific":"Pinus mugo","synonyms":[],"aliases":["mountain pine","mugo pine","Swiss mountain pine"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"2","zoneMax":"7","zoneNote":"Very hardy, generally zones 2–7. A mountain species that prefers cool roots and good light. It can sulk in hot, humid lowland summers.","rootMinF":5,"protectBelowF":15,"bringInBelowF":null,"potNote":"Hardy, but still insulate a shallow pot in severe cold and protect needles from winter wind. Treat any potted pine as less hardy than the same tree in the ground.","dormancy":"Cold outdoor rest is required.","winterizing":["Keep outdoors or in a bright cold frame.","Insulate the pot for deep cold, and provide a windbreak.","Do not bring it into a heated house."],"wateringWinter":"Water when the mix begins to dry, on milder days. Do not let an evergreen pine sit bone-dry in the wind.","lightWinter":"Full light, cold air.","repotWhen":"Early spring","repotCue":"As buds swell, before candles elongate","repotMonths":[3,4],"repotFreq":"Every 2–4 years, watching the breakdown of the mix","repotNotes":"Very free-draining mix. Mugo often has dense, compact roots; work carefully and keep some old soil. Some nursery mugos are grafted or have awkward roots — take time at the first repot.","rootPruning":"Moderate and careful at spring repotting.","structuralPruning":"Late summer or autumn for larger cuts. Naturally dense and shrubby — you often have to choose a clear trunk line from a bushy nursery plant.","pinching":"Shorten candles in late spring. The species is compact and can pack too much interior foliage; thin to keep pads airy.","wiring":"Autumn to early spring. Branches can be stiff and dense; work slowly.","fertilizing":"Moderate spring to mid-summer; stop by late summer.","pests":"Scale, sawfly, needle diseases in stagnant air, and root decline in wet mix. Good sun and airflow are essential.","leaf":{"group":"needle","arrangement":"fascicle-2","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Needles in pairs, short (often 1–2 inches), stiff, dark green, densely packed","evergreen":true,"features":"Two short, stout needles per bundle; a dense, shrubby habit. Needles are usually darker and shorter than Scots pine, and the bark is not brightly orange."},"facts":["A popular beginner pine because it is hardy, compact, and widely sold in nurseries.","In the Alps it grows as a shrubby mountain pine, which is why so many nursery plants start out bushy rather than tree-like.","Giving it a clear trunk and open pads is often the first design task when converting a garden mugo into bonsai."],"calendar":{"1":"Dormant. Keep the tree cold and protected from drying wind. Water when the root ball starts to dry — evergreens still transpire. No fertilizer.","2":"Late dormancy. In milder zones, prepare for early-spring repotting of trees that need it. Keep protection in place through the coldest nights.","3":"Preferred repotting window in most climates, as buds swell and before candles elongate strongly. Use a free-draining, grit-heavy mix. Wait several weeks before fertilizing a newly repotted tree.","4":"Candles extend. Begin a regular fertilizer program on established trees. Watch for sawfly and needle cast. Wiring is possible but buds are easy to knock off.","5":"Candle work begins in many climates: shorten or select candles according to the tree’s strength and style. Keep watering even. Full sun is usually preferred.","6":"Peak candle-pruning / decandling season for black pine on a two-flush program (timing is local — often early to mid-June in much of the U.S., later in cool-summer areas, earlier in the South). Reduce fertilizer briefly around decandling.","7":"New shoots harden. Resume fertilizing after decandling once new buds are visible. Needle thinning can begin on strong trees. Avoid heavy root work in high heat.","8":"Continue light needle work if needed. Taper fertilizer late in the month. Watch for mites and summer drought stress.","9":"Stop nitrogen so the tree hardens. Autumn needle thinning is traditional on some pines. Check wires. Do not repot in the North.","10":"Good month for wiring while the tree is slowing and wood is less brittle than in deep winter. Reduce water slightly. Prepare winter wind protection.","11":"Set up winter protection: a cold frame, windbreak, or unheated space, and mulch or wrap the pot. Evergreen foliage must not sit in a warm, dark room.","12":"Check water on mild days. Sun and wind can desiccate foliage even in the cold. Keep the tree firmly dormant and cold."}},{"id":"juniperus-procumbens","common":"Procumbens juniper","scientific":"Juniperus procumbens","synonyms":["Juniperus communis var. procumbens"],"aliases":["dwarf Japanese juniper","Procumbens nana","shohin juniper"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"9","zoneNote":"Generally zones 4–9. The widely sold ‘Nana’ is a compact form. Heat-tolerant compared with many mountain conifers, but not a houseplant.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Outdoor only in winter. Protect the pot below about 20°F, and shield foliage from drying wind. Roots in small pots may be hurt in the low teens.","dormancy":"Must experience a cold winter rest. Indoor heat and dry air almost always lead to slow decline, even if the tree looks all right for a few months.","winterizing":["Keep the tree outside or in a cold, bright frame or unheated space that stays cold.","Insulate the pot and provide a windbreak before severe freezes.","Do not overwinter it on a warm windowsill as a long-term plan.","If you use an unheated garage, it must stay cold and still get as much light as you can manage — junipers are evergreen."],"wateringWinter":"Water when the mix begins to dry. Evergreen foliage transpires all winter, especially in wind and sun.","lightWinter":"Full light. Avoid a dark, warm room.","repotWhen":"Early spring","repotCue":"As the tree wakes and tips just begin to grow, before a strong flush","repotMonths":[3,4],"repotFreq":"Every 2–3 years when young; every 3–5 years when mature","repotNotes":"Very free-draining mix. Junipers like oxygen at the roots. Do not bareroot a weak tree. Spring is safest.","rootPruning":"Moderate, at spring repotting. Leave a healthy fine-root mass.","structuralPruning":"You can cut to shape almost any time of the growing season, but large cuts are often made in spring or late summer. Never cut a juniper branch back to bare wood with no foliage — that section usually will not bud again.","pinching":"Pinch soft new tips with your fingers (not shears) on scale or fine growth, so you do not leave brown cut ends. ‘Procumbens’ is mostly sharp, awl-shaped juvenile foliage; trim carefully and thin crowded areas for airflow.","wiring":"Excellent wiring subjects. Autumn through early spring is ideal, but they can be wired in the growing season if you are gentle. Juniper wood is flexible when young and becomes very hard. Deadwood (jin and shari) is traditional.","fertilizing":"Regular from spring through mid-summer on established trees; taper by late summer. No winter feed. Wait after a repot.","pests":"Spider mites (especially in hot, dry weather — rinse or treat early), scale, and juniper tip blight. Good airflow is essential. Wet soil leads to root rot.","leaf":{"group":"needle","arrangement":"whorled","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Sharp, awl-shaped needles, usually in whorls of three, crowded along the shoot","evergreen":true,"features":"Mostly juvenile, needle-like foliage (unlike Shimpaku, which is mostly scale-like). Needles are stiff and prickly. The habit is naturally low and creeping unless it is trained upward. Foliage is typically bright to mid green."},"facts":["‘Procumbens Nana’ is one of the most common nursery junipers converted into bonsai, especially informal or cascade styles.","Unlike many Chinese junipers, it usually keeps its sharp juvenile needles rather than graduating to soft scale foliage.","It is often the first juniper people try — hardy and wireable, but it still must live outside in winter."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Pinch soft tips as they extend. Keep the tree in full sun with good airflow.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch for spider mites in dry heat; a periodic spray of the foliage with water (not on the pot soil) can help.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"juniperus-chinensis","common":"Shimpaku / Chinese juniper","scientific":"Juniperus chinensis","synonyms":["Juniperus sargentii"],"aliases":["shimpaku","Sargent juniper","Chinese juniper","itoigawa"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"9","zoneNote":"Most Chinese junipers used in bonsai are hardy in roughly zones 4–9, with some variation by clone. Itoigawa and many shimpaku types are classic bonsai cultivars.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Outdoor winter is required. Insulate the pot below about 20°F and protect foliage from winter wind and sun scorch.","dormancy":"Cold rest outdoors or in a cold frame. Not a houseplant.","winterizing":["Keep outside or in a bright, cold frame.","Wrap, mulch, or plunge the pot before severe cold, and break the wind.","Do not store it all winter in a heated house."],"wateringWinter":"Water when the mix starts to dry; evergreen pads still transpire.","lightWinter":"Full light and cold air.","repotWhen":"Early spring","repotCue":"As growth just begins, before a strong flush","repotMonths":[3,4],"repotFreq":"Every 2–3 years when young; every 3–5 years when mature","repotNotes":"Sharp-draining mix. Preserve fine roots. Spring is the conservative season; some experienced growers also work them in early autumn in mild climates, but that is riskier in the North.","rootPruning":"Moderate, at repotting. Do not strip a weak juniper bare.","structuralPruning":"Junipers will not bud from bare wood. Always leave foliage on a branch you want to keep. Jin and shari are traditional on this species. Larger cuts are often made in spring or late summer.","pinching":"Pinch new scale-foliage tips with fingers. Thin crowded pads so light and air reach the interior; inner foliage that stays dark will brown. Avoid shearing into a formal hedge, which browns the tips.","wiring":"A premier wiring tree. Autumn to spring is ideal. Young branches are very flexible; older ones need patience and, sometimes, raffia. Check wires so they do not bite a pad.","fertilizing":"Steady from spring to mid-summer; taper late summer. No winter fertilizer.","pests":"Spider mites, scale, tip blight, and bagworms in some regions. Mites thrive in dry heat. Good sun and airflow prevent many problems.","leaf":{"group":"scale","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Soft, scale-like foliage in feathery sprays; occasional patches of sharp juvenile needles","evergreen":true,"features":"Adult foliage is scale-like and relatively soft (the shimpaku look), in flattened or slightly rounded sprays. Juvenile awl-shaped needles may appear on young or stressed shoots. No white ‘X’ or ‘Y’ stomatal marks on the underside like hinoki cypress. Foliage color ranges from green to blue-green, depending on the cultivar."},"facts":["Shimpaku is the classic bonsai juniper of Japan; Itoigawa is a particularly fine-foliaged strain.","Juniperus chinensis is a wide species group; Sargent juniper (often called J. chinensis var. sargentii or J. sargentii) is closely related and used in similar ways.","Striking live-vein and deadwood (shari and jin) designs are traditional, echoing ancient trees on cliffs and mountains."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Pinch or cut new growth according to the species (see the care notes). Full sun or the light recommended for the species. Regular water and fertilizer.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch heat and drought. Many mountain conifers appreciate a little afternoon shade in hot regions. Keep watering evenly.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"ficus-microcarpa","common":"Chinese banyan / Ficus retusa","scientific":"Ficus microcarpa","synonyms":["Ficus retusa","Ficus nitida"],"aliases":["Chinese banyan","ginseng ficus","tiger bark ficus","Ficus retusa"],"family":"Moraceae","place":"indoor","climate":"tropical","zoneMin":"9b","zoneMax":"11","zoneNote":"A tropical and subtropical tree. Outdoors year-round only in roughly zones 9b–11, and even there a rare cold snap can damage it. Everywhere else it is an indoor or indoor/outdoor tree.","rootMinF":40,"protectBelowF":55,"bringInBelowF":55,"potNote":"Do not let it freeze — damage begins well above 32°F. Bring it in before nights drop into the low 50s°F (about 10–13°C). Brief spells in the mid-40s may be tolerated by a hardier tree, but that is not a safe plan.","dormancy":"No true cold dormancy. Growth slows in short winter days. A slightly lighter fertilizer and water schedule is enough of a rest.","winterizing":["Move indoors before chilly nights in the low 50s°F.","Inspect for pests first.","Give the brightest window or a grow light; avoid cold drafts and heating vents.","Expect some leaf drop after the move — usually temporary if light and water are reasonable.","Do not leave it outside for a ‘taste of fall’ once nights are cold."],"wateringWinter":"Water when the top of the mix begins to dry. Indoor trees in short days need less water than they did in summer, but Ficus also hates staying bone-dry. Use room-temperature water.","lightWinter":"Maximum practical light. A south or west window, or supplemental light, prevents weak internodes.","repotWhen":"Late spring through summer, when nights are warm and the tree is growing strongly","repotCue":"Active growth and consistently warm conditions — never on a cold, slow tree","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"They tolerate fairly hard root work in warmth. A free-draining tropical mix is fine. Keep the tree warm and slightly more humid after a repot. Do not repot just before a move into a dim winter room.","rootPruning":"Can be relatively assertive on a healthy tree in summer. Aerial roots can be trained in a humid environment and are part of the banyan look.","structuralPruning":"Year-round when the tree is growing. Cuts often bleed white latex — not usually serious. It back-buds well on old wood compared with many trees.","pinching":"Pinch or clip shoots during the growing season to build ramification. Defoliation of healthy trees in summer is sometimes used to reduce leaf size.","wiring":"When growing, with care; bark marks easily and branches can be a bit brittle. Raffia or tape helps on larger bends. Wiring in summer after a defoliation makes placement easier.","fertilizing":"Regularly during active growth (late spring through early autumn). In winter, feed little or not at all unless the tree is under strong lights and still growing.","pests":"Scale, mealybugs, spider mites, thrips, and sooty mold on honeydew. Indoor dry air encourages mites. The milky sap can irritate skin; keep sap away from eyes.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Oval to elliptic, leathery, often with a short drip tip","evergreen":true,"features":"Alternate, simple, glossy evergreen leaves with a smooth margin and a slightly thickened feel. Broken leaves or a cut twig exude white milky sap. Older trees may produce aerial roots. ‘Tiger bark’ forms show mottled bark; ‘ginseng’ ficus in shops is often a thick-rooted grafted cutting of this or a close form."},"facts":["Ficus retusa is a name you will still see in bonsai shops; most of those trees are Ficus microcarpa.","In the tropics it is a true banyan, dropping aerial roots that can become pillar trunks.","It is one of the best indoor bonsai for beginners because it back-buds freely and forgives a range of mistakes — except cold."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"ficus-benjamina","common":"Weeping fig","scientific":"Ficus benjamina","synonyms":[],"aliases":["weeping fig","Benjamin fig"],"family":"Moraceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"Tropical; outdoor year-round only in zones 10–11, and even there it wants protection from cold wind. Slightly more easily stressed by sudden moves than Ficus microcarpa.","rootMinF":42,"protectBelowF":55,"bringInBelowF":55,"potNote":"Bring indoors before nights in the low 50s°F. Do not expose it to frost. Sudden changes in light or location often cause a dramatic leaf drop, which is usually temporary.","dormancy":"No cold dormancy. It may rest a little in short days.","winterizing":["Bring in before nights reach the low 50s°F.","Check for pests.","Place in the brightest stable spot you have, and then leave it there — it resents being shuffled.","Accept some leaf drop after the move; resume a steady water and light routine rather than overwatering in panic."],"wateringWinter":"When the surface begins to dry. Overwatering after leaf drop is a common mistake.","lightWinter":"Bright, stable light. Avoid drafty doors and heat registers.","repotWhen":"Late spring and summer, in active growth","repotCue":"Warm nights and a tree that is pushing new leaves","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Warmth after repotting is important. Free-draining tropical mix. Avoid a repot just as you bring the tree indoors for winter.","rootPruning":"Moderate to fairly firm on a healthy summer tree. Less aggressive than you might be with F. microcarpa if the tree is thin or has just dropped leaves.","structuralPruning":"During the growing season. It has a naturally weeping habit — design with or against that on purpose. White latex flows from cuts.","pinching":"Clip growing tips through summer to counter the long internodes it can make in low light.","wiring":"With care; branches can be brittle and the bark marks. Summer, when leaves are present or after a planned defoliation, is usual.","fertilizing":"Regular in the growing season; little or none in a dim winter.","pests":"Scale, mites, mealybugs, and thrips. Leaf drop from drafts, low light, or soggy soil is the complaint most owners meet first.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Oval with a long, slender drip tip; thinner and more glossy than Ficus microcarpa","evergreen":true,"features":"Alternate evergreen leaves, usually more slender and longer-tipped than Chinese banyan, on slightly weeping twigs. White milky sap. Bark is generally smoother and paler than tiger-bark microcarpa."},"facts":["A very common houseplant, and a capable indoor bonsai if it gets enough light.","It is famous for dropping leaves when you move it; consistency of placement is half the care.","The long drip tip is an adaptation for shedding tropical rain, and it is the quickest way to separate it from the broader-leaved F. microcarpa."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"ficus-salicifolia","common":"Willow-leaf ficus","scientific":"Ficus salicifolia","synonyms":["Ficus neriifolia","Ficus angustifolia"],"aliases":["willow leaf fig","narrow-leaf ficus","Ficus neriifolia"],"family":"Moraceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"Tropical; year-round outdoors only in zones 10–11. A favorite indoor bonsai because the narrow leaves already look in scale.","rootMinF":42,"protectBelowF":55,"bringInBelowF":55,"potNote":"Bring in before nights in the low 50s°F. No frost. Handles indoor life well if light is strong.","dormancy":"No cold dormancy; a slower winter under weaker light is normal.","winterizing":["Indoors before the low 50s°F.","Pest check, then a bright, stable window or grow light.","Water a little less in the short days, but do not dry it out hard."],"wateringWinter":"When the surface starts to dry. Room-temperature water.","lightWinter":"The brightest you can offer.","repotWhen":"Late spring through summer","repotCue":"Warmth and active growth","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Standard tropical practice: free-draining mix, warm recovery, no late-autumn repot in a cold house.","rootPruning":"Fairly assertive in summer on a healthy tree. Recovers well.","structuralPruning":"Year-round while growing. Back-buds well. Fine ramification is easier than on large-leaved figs.","pinching":"Frequent pinching in the growing season keeps the willow-like shoots from running long.","wiring":"During growth, with the usual Ficus caution for bark marks and some brittleness.","fertilizing":"Regularly in the growing season; little in winter unless it is growing under strong lights.","pests":"Scale, mites, mealybugs. White sap can irritate skin.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Long, narrow, willow-like leaves with a smooth margin","evergreen":true,"features":"Alternate, slender leaves that already look to-scale on a small tree — the main ID feature versus other Ficus bonsai. Milky sap when cut. Evergreen."},"facts":["The narrow leaf is why so many growers pick this Ficus for smaller bonsai.","You will also see it labeled Ficus neriifolia; naming in the trade is messy, but care is the same.","Like its cousins, it can be defoliated in summer on a strong tree to tighten internodes."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"crassula-ovata","common":"Jade plant","scientific":"Crassula ovata","synonyms":["Crassula argentea"],"aliases":["jade","money plant","friendship tree"],"family":"Crassulaceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"A South African succulent, hardy outdoors only in roughly zones 10–11, and even there a frost can scar the leaves. Treat it as frost-tender everywhere else.","rootMinF":40,"protectBelowF":45,"bringInBelowF":45,"potNote":"Damage can begin around 40°F, and frost will pulp the leaves. Bring it in before nights drop into the mid-40s°F. A cool, bright indoor winter is better than a dark, hot one.","dormancy":"No freezing dormancy. It often rests in short days and, if kept cool and bright, may even flower in winter or early spring.","winterizing":["Bring indoors before nights in the mid-40s°F.","Give a bright, cool window.","Water much less — this is a succulent at rest in short days.","Keep it off cold window glass on freezing nights."],"wateringWinter":"Infrequently, when the pot is dry and the leaves just begin to soften. Overwatering in winter is the usual way to lose a jade.","lightWinter":"Bright light, even full sun in a window. Weak light plus winter water leads to rot and stretch.","repotWhen":"Late spring or summer","repotCue":"Warm, bright conditions and a tree that is growing, not a wet, dormant winter plant","repotMonths":[5,6,7],"repotFreq":"Every 2–3 years, or when the pot is crowded; they like a slightly snug pot","repotNotes":"A very mineral, fast-draining succulent or cactus-style mix. Do not overpot. Let cuts on roots dry slightly before watering thoroughly. Avoid winter repotting.","rootPruning":"Light to moderate. They do not need a huge root mass, but they can be unstable (top-heavy) if you cut too much at once. Work in the growing season.","structuralPruning":"During the growing season. Branches snap rather than bend, so pruning (clip-and-grow) is often more useful than heavy wiring. Let cuts dry and callus.","pinching":"Pinch or cut tips to force branching; each cut usually produces two new shoots. Remove opposite leaves at a node if you want a cleaner branch line.","wiring":"Limited: flesh is brittle and marks easily. If you wire, do it lightly on younger stems in the growing season, or use guy wires.","fertilizing":"Lightly during spring and summer growth. Little or no fertilizer in winter.","pests":"Mealybugs (check leaf axils), scale, and root mealybugs. The serious cultural problem is rot from winter wet and poor light.","leaf":{"group":"succulent","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Thick, fleshy, oval to spoon-shaped, glossy green, sometimes with a red edge in strong sun","evergreen":true,"features":"Opposite pairs of succulent leaves, much thicker and larger than Portulacaria. Stems become woody and thick with age. No milky sap. Leaves are smooth and juicy if broken."},"facts":["In strong sun the leaf edges often blush red, which is a healthy sign, not a deficiency.","Old jade plants become genuinely tree-like, with thick trunks that make surprisingly convincing bonsai.","It is sometimes confused with Portulacaria afra (dwarf jade), which has much smaller leaves and reddish, thinner stems."],"calendar":{"1":"Cool, bright, and almost dry. If the tree is happy it may set small starry winter flowers. Do not water on a schedule — water when the leaves just soften.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Same careful winter rest. Keep leaves off icy glass."}},{"id":"portulacaria-afra","common":"Dwarf jade / elephant bush","scientific":"Portulacaria afra","synonyms":[],"aliases":["dwarf jade","elephant bush","spekboom","miniature jade"],"family":"Didiereaceae","place":"indoor","climate":"tropical","zoneMin":"9b","zoneMax":"11","zoneNote":"South African succulent, generally outdoor-hardy only in about 9b–11, and even then a hard frost can take it down. Slightly more forgiving of brief cool nights than some jades, but still not frost-hardy.","rootMinF":38,"protectBelowF":45,"bringInBelowF":45,"potNote":"Bring in before nights in the mid-40s°F. Do not let it freeze. A bright, cool indoor winter with little water is ideal.","dormancy":"No freeze dormancy. Growth slows in short days if you keep it cool and dry.","winterizing":["Indoors before mid-40s°F nights.","Bright light, cool room if possible, and much less water.","Keep foliage off freezing window glass."],"wateringWinter":"Rarely. Let the pot dry and the leaves soften slightly first. Winter rot is the main indoor killer.","lightWinter":"Maximum light.","repotWhen":"Late spring or summer","repotCue":"Warmth and active growth","repotMonths":[5,6,7],"repotFreq":"Every 2–3 years, or when root-bound","repotNotes":"Fast-draining succulent mix. Do not leave it in a peat-heavy nursery soil. Let root cuts dry before a thorough watering.","rootPruning":"Light to moderate in the growing season.","structuralPruning":"Grows quickly in heat and sun. Clip often to build ramification; it back-buds well. Stems are thinner and more flexible than jade, but still can snap.","pinching":"Frequent pinching is the main styling tool. It ramifies into a very fine, small-leaved tree.","wiring":"Possible on younger reddish stems, with care. Clip-and-grow does most of the work.","fertilizing":"Lightly in the growing season only.","pests":"Mealybugs and occasional aphids on soft growth. Overwatering is more dangerous than insects.","leaf":{"group":"succulent","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Small, round to oval succulent leaves, much smaller than true jade","evergreen":true,"features":"Opposite pairs of small, pad-like leaves on thin, often reddish or burgundy stems. Leaves are typically ¼–½ inch, not the thick spoons of Crassula ovata. A very different plant family from true jade, despite the nickname."},"facts":["Called spekboom in South Africa, where it is an important fodder and carbon-storing shrub of the thicket.","It is the better ‘jade’ for small bonsai because the leaves are already tiny and the internodes can be kept short.","Elephants really do browse it in its native range — hence ‘elephant bush’."],"calendar":{"1":"Bright, cool, and dry. Water only when the small leaves soften.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"ligustrum-sinense","common":"Chinese privet","scientific":"Ligustrum sinense","synonyms":[],"aliases":["Chinese privet"],"family":"Oleaceae","place":"both","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"Often listed as zones 6–9 or 7–10. Semi-evergreen in mild winters, deciduous in colder ones. In many parts of the U.S. it is an invasive plant in the landscape — keep berries and trimmings contained, and do not plant it out.","rootMinF":18,"protectBelowF":28,"bringInBelowF":null,"potNote":"Protect potted trees as nights fall into the upper 20s°F. Root damage becomes more likely around the high teens. In cold zones, a cold frame or unheated space is safer than an exposed bench.","dormancy":"Takes a cool rest and may drop leaves in the cold. A warm indoor winter is possible with bright light, but a cool rest produces tighter growth the following year.","winterizing":["In zones 8–9, pot protection from freezes may be enough.","In zones 6–7, insulate the pot or move to a cold frame or unheated space, roughly in the 30–50°F range.","If overwintered indoors, give bright light and expect some leaf drop."],"wateringWinter":"Reduced; never bone-dry. Trees that hold leaves need a bit more water than leafless ones.","lightWinter":"Good light if evergreen; cold leafless trees can take lower light.","repotWhen":"Late winter to early spring","repotCue":"As buds swell or just as new leaves start","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Fast rooter. Standard free-draining mix. Recovers well from spring root work.","rootPruning":"Fairly assertive on a healthy spring tree.","structuralPruning":"Back-buds readily. Heavy cuts in late winter or after a flush. A very forgiving clip-and-grow tree.","pinching":"Pinch often in the growing season; it ramifies quickly and is used for small-leaved formal and informal uprights.","wiring":"Young wood is flexible. Check wires — growth is fast.","fertilizing":"Regularly in the growing season; taper if the tree will face a real winter.","pests":"Scale, whitefly, spider mites (indoors), and sooty mold. Leaf spots in stagnant, wet conditions.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Small, elliptic to ovate, usually with a smooth or barely wavy margin","evergreen":false,"features":"Opposite simple leaves, typically 1–2 inches, thinner than Japanese privet and often a bit paler. May be semi-evergreen. Small white flower panicles and dark berries if not pinched. Stems are slender."},"facts":["A beginner-friendly tree that ramifies quickly and reduces leaf size well.","Chinese privet is invasive in much of the southeastern U.S.; as a bonsai, prevent it from seeding into the garden.","It can be grown almost as a tropical (indoor winter) or as a hardy deciduous tree, depending on your climate."],"calendar":{"1":"In the South it may still hold leaves; protect the pot from freezes. In the North it is usually leafless and should stay cold.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"ligustrum-japonicum","common":"Japanese privet","scientific":"Ligustrum japonicum","synonyms":[],"aliases":["wax-leaf privet","Japanese privet"],"family":"Oleaceae","place":"both","climate":"subtropical","zoneMin":"7","zoneMax":"10","zoneNote":"Typically zones 7–10, a bit less hardy than Chinese privet. More reliably evergreen, with thicker, waxy leaves.","rootMinF":20,"protectBelowF":30,"bringInBelowF":null,"potNote":"Protect potted trees near freezing. In zone 7, a cold frame or unheated space is wise. Not as hardy as many maples.","dormancy":"Evergreen, but growth slows in the cold. A cool, bright winter is better than a hot, dim room.","winterizing":["Protect the pot as nights approach freezing.","In colder parts of its range, use a cold frame or cool bright indoor spot.","Keep it from dry indoor heat if you can; a cool window is better."],"wateringWinter":"When the surface begins to dry. Evergreen foliage still transpires.","lightWinter":"Bright light.","repotWhen":"Late winter to spring, or early summer in warm climates","repotCue":"As growth begins in spring","repotMonths":[3,4,5],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining mix. Recovers well in warmth. Avoid a late-autumn repot in the North.","rootPruning":"Moderate to fairly firm in spring on a healthy tree.","structuralPruning":"Back-buds well. Clip-and-grow through the growing season; heavier cuts in spring.","pinching":"Pinch often; the larger, waxy leaves need consistent shooting to stay in scale.","wiring":"Young branches wire well. Watch for bite marks on fast growth.","fertilizing":"Regular in the growing season; lighter in winter if it is still growing in a mild climate.","pests":"Scale, whitefly, mites, and sooty mold. Thrips sometimes mark the thick leaves.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Thick, waxy, ovate to elliptic evergreen leaves with a smooth margin","evergreen":true,"features":"Opposite, leathery, glossy leaves, usually larger and thicker than Chinese privet. Clearly evergreen in most climates. Twigs are stouter. White flower clusters and black berries if allowed to bloom."},"facts":["The thick, waxy leaf is the quick way to tell it from Chinese privet.","It is widely used as a hedge, and those same dense branching habits make it a solid bonsai subject.","In a cold snap the leaves may bronze; usually they recover if the roots were protected."],"calendar":{"1":"Evergreen — give light, protect the pot, and water modestly.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Protection should be ready before a hard freeze. Do not keep it in a hot, dark room if you can give it a cool, bright one.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"ehretia-microphylla","common":"Fukien tea","scientific":"Ehretia microphylla","synonyms":["Carmona retusa","Carmona microphylla","Ehretia buxifolia"],"aliases":["Fukien tea","Philippine tea","Carmona"],"family":"Boraginaceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"A tropical shrub. Outdoors year-round only in zones 10–11. Famous as a shop ‘indoor bonsai,’ and also famous for being fussy about dryness and sudden change.","rootMinF":50,"protectBelowF":55,"bringInBelowF":55,"potNote":"Bring in before nights in the low 50s°F. Do not let it get cold, drafty, or bone-dry. It is less forgiving than Ficus.","dormancy":"No cold dormancy. It prefers steady warmth and humidity.","winterizing":["Indoors well before nights reach the low 50s°F.","Bright light and a stable, moderately humid spot away from vents and drafty doors.","Do not let the pot dry out hard — this is the usual cause of sudden leaf and flower drop.","A humidity tray or nearby humidifier helps in heated houses."],"wateringWinter":"Evenly moist but not soggy. It dislikes a full dry-down more than Ficus does. Use room-temperature water.","lightWinter":"Bright light, with a little protection from a scorching, dry radiator-side window if the pot is drying too fast.","repotWhen":"Late spring and summer only","repotCue":"Warm, active growth","repotMonths":[5,6,7],"repotFreq":"Every 1–2 years, or when the mix has soured","repotNotes":"Free-draining but moisture-retentive tropical mix. Do not strip the roots bare, and do not repot in winter. Keep humidity up afterward.","rootPruning":"Moderate, and only in the growing season on a healthy tree. Conservative is safer.","structuralPruning":"During growth. It ramifies well and often flowers on short shoots. Avoid heavy cuts when the tree is stressed or dropping leaves.","pinching":"Light, regular pinching in the growing season. Leave some shoots if you want the small white flowers.","wiring":"Young branches can be wired carefully. Older wood is stiffer. Do not wire a stressed tree.","fertilizing":"Light, regular feeding in the growing season. Little in winter unless it is clearly growing under strong light.","pests":"Scale, mealybugs, spider mites, and aphids. Sudden leaf drop is more often cultural (dry pot, cold draft, low humidity) than a single pest.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"crenate","shape":"Small, obovate, slightly rough leaves, often with a rounded tip and shallow teeth","evergreen":true,"features":"Alternate, small (often ½–1 inch) leaves, a bit scabrous or leathery, with shallow crenate teeth. Some leaves show tiny pale dots. Small white starry flowers and red to orange berries may appear on a happy tree. Evergreen."},"facts":["Named for Fujian (Fukien) province in China, though the species is widespread in East and Southeast Asia.","It is still widely sold as Carmona retusa; botanists now place it in Ehretia.","Those tiny white flowers and red berries are a joy when you get the watering and humidity right."],"calendar":{"1":"The most dangerous month indoors: dry heat and short days. Keep moisture and light as even as you can.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"serissa-japonica","common":"Serissa / snow rose","scientific":"Serissa japonica","synonyms":["Serissa foetida"],"aliases":["snow rose","tree of a thousand stars","Serissa foetida"],"family":"Rubiaceae","place":"indoor","climate":"subtropical","zoneMin":"8","zoneMax":"10","zoneNote":"Sometimes listed as hardy to zone 8, but potted trees are tender and resent sudden change. In most of the U.S. it is an indoor/outdoor or indoor tree. Protect it well above freezing.","rootMinF":40,"protectBelowF":45,"bringInBelowF":45,"potNote":"Bring in before nights in the mid-40s°F. Even a brief chill plus a dry pot can cause a dramatic leaf drop. Treat it as tender in a shallow container.","dormancy":"No hard dormancy. It likes a cool (not cold), bright winter rest rather than a hot, dry living room.","winterizing":["Indoors or into a cool greenhouse before mid-40s°F nights.","Bright light, even moisture, and no cold drafts.","Expect some leaf or flower drop after a move; stabilize care rather than making many changes at once."],"wateringWinter":"Keep evenly moist; it dislikes drying out and also dislikes sitting in a saucer of water. Consistency is everything.","lightWinter":"Bright light. A cool bright room is better than a warm dark one.","repotWhen":"Late spring or early summer","repotCue":"Warmth and a tree that is growing, not a recently defoliated or stressed tree","repotMonths":[5,6],"repotFreq":"Every 1–2 years","repotNotes":"Free-draining but moisture-retentive mix. Be conservative with roots. Avoid winter and autumn repotting in the North.","rootPruning":"Light to moderate, only in the growing season.","structuralPruning":"During growth. It ramifies finely and flowers on new and older short shoots. Heavy cuts on a stressed tree often trigger leaf drop.","pinching":"Light pinching after flushes. If you want flowers, do not pinch away every new shoot.","wiring":"Young, thin twigs can be wired very gently. The wood is fine and marks or snaps easily.","fertilizing":"Light, regular feeding in the growing season. Little in winter.","pests":"Spider mites, aphids, and scale. The bigger ‘pest’ is inconsistent watering and moving the tree around.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Tiny, ovate, opposite leaves, sometimes slightly hairy","evergreen":true,"features":"Very small opposite leaves, often ¼–½ inch, on fine twigs. Crushed leaves and bark have a strong, unpleasant odor (the old name foetida). Small white or pink star-like flowers. Some cultivars are variegated."},"facts":["The old botanical name Serissa foetida refers to the rank smell of crushed leaves — a useful ID trick.","It is nicknamed ‘tree of a thousand stars’ for the profusion of tiny flowers when it is happy.","It has a reputation for being temperamental; most failures trace back to letting the pot dry, then overwatering, or to cold drafts."],"calendar":{"1":"Cool, bright, and evenly moist. Avoid both bone-dry and soggy. Do not reshuffle its position constantly.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"rhododendron-indicum","common":"Satsuki azalea","scientific":"Rhododendron indicum","synonyms":["Rhododendron eriocarpum"],"aliases":["Satsuki azalea","azalea bonsai"],"family":"Ericaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"Many Satsuki and related evergreen azaleas are listed around zones 6–9 or 7–9; cultivars vary. They need a real winter rest but not a frozen-solid root ball.","rootMinF":18,"protectBelowF":25,"bringInBelowF":null,"potNote":"Protect pots below the mid-20s°F. Roots in specialized, open azalea soils can freeze and dry quickly. Do not overwinter in a warm house — flower buds need a cold rest.","dormancy":"Requires a cool to cold winter rest to set and hold flower buds. Keep it outdoors or in a cold frame, not in a heated living room.","winterizing":["Leave the tree outside or in a bright cold frame through autumn so it hardens and receives chill.","Insulate the pot and block wind before regular nights in the mid-20s°F.","An unheated space in the high 20s to 40s°F can work if light is decent and the tree stays cold.","Do not let the fine, shallow roots dry out in a winter wind."],"wateringWinter":"Never let an azalea go bone-dry. The fibrous roots are sensitive to drought even in winter. Use soft or rain water if your tap water is very hard or alkaline.","lightWinter":"Good light, with some protection from harsh winter sun and wind, which can scorch evergreen leaves.","repotWhen":"After flowering, typically late spring to early summer","repotCue":"When the last flowers are fading, before the summer heat peaks","repotMonths":[5,6],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature, or when the kanuma or organic mix has broken down","repotNotes":"Use an acid, open azalea medium (kanuma is traditional; an acidic, well-aerated mix is the principle). Do not use strongly alkaline soil or limey water if you can avoid it. Be respectful of the fine, dense roots — comb them out carefully rather than hacking. Spring before bloom is sometimes used, but immediately after bloom is the usual, conservative window.","rootPruning":"Careful and moderately firm at the post-bloom repot. Keep plenty of fine feeding roots. Do not bareroot a weak azalea.","structuralPruning":"Right after flowering: that is when you shape the tree and reduce the shoots that have just bloomed. Flowers (and next year’s buds) form on wood made after this prune, so a late-summer or autumn cut can remove the following year’s bloom.","pinching":"After the post-flower pruning, pinch or shorten the new flush to one or two leaves once it extends, unless you are letting a shoot run for strength or design.","wiring":"After flowering, with great care — azalea wood is brittle and snaps with little warning. Many growers prefer clip-and-grow plus a little gentle wire. Use raffia for any serious bend, and do not wire in a drought.","fertilizing":"Use an acid-forming or azalea/rhododendron fertilizer. Feed after flowering through mid-summer; taper late. Do not force a tree with hard fertilizer just as it goes into winter, and be gentle right after repotting.","pests":"Lace bugs, spider mites, azalea caterpillars, root weevils, and chlorosis from alkaline water or soil. Petal blight on flowers in wet weather. Never let the pot dry, then flood it.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Small, elliptic, slightly hairy evergreen leaves, often clustered near the tips","evergreen":true,"features":"Alternate but often bunched at shoot tips. Leaves are generally ½–1½ inches, with a slightly rough or hairy feel and a smooth or faintly ciliate margin. Evergreen in most winters. Spectacular late-spring flowers in almost every color except true blue, often variegated on Satsuki cultivars."},"facts":["‘Satsuki’ refers to the fifth month of the traditional Japanese calendar, when these azaleas bloom — later than many garden azaleas.","They are show trees in Japan, often displayed in full flower with a huge range of patterned blooms, sometimes several patterns on one tree.","Kanuma, a lightweight acidic Japanese soil, is the traditional potting medium and is one reason azalea bonsai have such a specialized routine."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Do not rush a repot before bloom unless you must. Protect swelling flower buds from a late freeze and from drying wind.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Peak bloom for many Satsuki, depending on climate. When flowers fade, prune, and — if needed — repot and root-prune.","6":"Main styling, pinching, and (if not done right after bloom) repotting month. Keep the fine roots evenly moist.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Do not prune hard or you may cut off next year’s flower buds. Stop fertilizer so the tree hardens.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"buxus-microphylla","common":"Japanese boxwood","scientific":"Buxus microphylla","synonyms":["Buxus microphylla var. japonica"],"aliases":["Japanese box","littleleaf boxwood","box"],"family":"Buxaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"Buxus microphylla is generally zones 6–9; common European box (B. sempervirens) is often listed 5–8. Cultivars and winter wind exposure matter a great deal.","rootMinF":12,"protectBelowF":20,"bringInBelowF":null,"potNote":"Evergreen and hardy, but winter burn and a frozen, dry pot are common. Protect pots below about 20°F and block winter wind and harsh sun.","dormancy":"A cold outdoor rest is best. A heated house produces weak, mite-prone growth.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot and provide a wind- and sun-break in harsh winter climates.","Do not let the evergreen foliage sit in a warm, dry room all winter."],"wateringWinter":"Water when the mix begins to dry. Evergreen leaves still transpire, and a dry boxwood in a winter wind burns badly.","lightWinter":"Good light, with some shelter from midwinter sun and wind in exposed sites.","repotWhen":"Early spring, as growth begins","repotCue":"Swelling buds or the first hint of new shoots","repotMonths":[3,4],"repotFreq":"Every 2–3 years, or when the pot is packed; they can live in a somewhat tight pot","repotNotes":"Well-draining mix; they are not swamp plants. Roots can be dense and woody — work them open carefully. Avoid late-autumn repotting in the North.","rootPruning":"Moderate at spring repotting. Do not remove a huge share of a weak or recently collected tree.","structuralPruning":"Responds well to cutting and back-buds on old wood better than many conifers. Heavy cuts in spring; maintenance clipping through the growing season.","pinching":"Shearing is traditional on hedges but for bonsai, cut back to a leaf or pair to avoid brown tips and a formal ‘meatball’ look. Thin the interior for light.","wiring":"Possible on younger branches; older boxwood is stiff and can snap. Clip-and-grow does a lot of the work. Wire in spring or autumn and check often.","fertilizing":"Moderate, from spring through mid-summer; taper late. They are not heavy feeders.","pests":"Boxwood leafminer, psyllid, mites, and — where it occurs — boxwood blight (a serious fungal disease; do not work a suspect tree next to healthy ones). Winter burn is cultural, not a pest.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Very small, elliptic, leathery evergreen leaves with a smooth margin, often slightly notched at the tip","evergreen":true,"features":"Opposite, tiny, glossy evergreen leaves, typically ¼–¾ inch. Arrangement and the often emarginate (notched) tip help separate it from Japanese holly, which has alternate, finely crenate leaves. No strong odor when crushed, unlike some Serissa. Stems are square-ish when young."},"facts":["Boxwood has been clipped into formal shapes for centuries, which is why it takes pruning so well as bonsai.","Japanese holly (Ilex crenata) is the usual look-alike; check leaf arrangement — opposite on boxwood, alternate on holly.","All parts of boxwood are considered toxic if eaten; keep trimmings away from pets that chew."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"A good month to do any needed repotting and to begin maintenance trimming as the new flush starts.","5":"Pinch or cut new growth according to the species (see the care notes). Full sun or the light recommended for the species. Regular water and fertilizer.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch heat and drought. Many mountain conifers appreciate a little afternoon shade in hot regions. Keep watering evenly.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"taxodium-distichum","common":"Bald cypress","scientific":"Taxodium distichum","synonyms":[],"aliases":["bald cypress","swamp cypress"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"10","zoneNote":"Remarkably wide range, generally zones 4–10. A deciduous conifer of swamps and river margins that still wants excellent drainage in a pot between waterings — ‘wetland’ does not mean ‘stagnant pot.’","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but protect a shallow pot below about 20°F. Needs a genuine winter rest; do not keep it indoors in the warmth.","dormancy":"Deciduous. Requires a cold winter. The feathery leaves color rust-brown and drop.","winterizing":["Let it harden and drop foliage outdoors.","Insulate or plunge the pot before severe cold.","An unheated garage is acceptable once it is leafless, if it stays cold and the pot does not dry out completely.","Do not overwinter in a heated house."],"wateringWinter":"The pot can stay more moist than a pine, but it should not be a frozen block of standing water. Do not let it go bone-dry.","lightWinter":"Low light is acceptable while leafless and cold. Return to sun as buds swell.","repotWhen":"Late winter to early spring, just as buds swell","repotCue":"Swelling buds, before the feathery flush extends","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young (very vigorous); every 2–3 years when mature","repotNotes":"A moisture-retentive but still open mix. They grow very fast and often need more frequent root work than pines. Knees almost never form in a small bonsai pot, which is normal.","rootPruning":"They tolerate fairly hard spring root pruning when healthy. Expect vigorous recovery.","structuralPruning":"Late winter, when the structure is visible, or during the growing season on a strong tree. It back-buds well for a conifer.","pinching":"Cut or pinch the feathery new growth during the season to keep pads and internodes in scale. They can run very long if ignored.","wiring":"After leaf-drop or before the spring flush, when you can see the wood. Young wood is flexible; older wood is brittle in hard cold.","fertilizing":"Regularly during the growing season; they are hungry. Stop by late summer to harden off.","pests":"Spider mites in hot, dry air, bagworms, and chlorosis in very alkaline water. The usual pot problem is swinging between bone-dry and stagnant.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Soft, feathery, deciduous needles arranged in two ranks on short shoots","evergreen":false,"features":"A deciduous conifer: soft, linear needles, generally two-ranked (flat sprays), turning rust or copper before they drop. Branchlets are mostly alternate (compare dawn redwood, which is opposite). Trunks become fluted with age. The ‘bald’ name refers to winter leaflessness."},"facts":["Bald cypress can live for many centuries in southern swamps, and old trees develop distinctive knees — rare in shallow bonsai pots.","It is one of the few deciduous conifers commonly used for bonsai, with beautiful autumn color and a stark winter silhouette.","Despite its wetland origin, a potted tree still needs oxygen at the roots; constant standing water in a closed pot is not the same as a living swamp."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Needles color a warm rust or copper before falling — one of the best autumn shows among conifers. After leaf-drop, wire and set winter protection.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"metasequoia-glyptostroboides","common":"Dawn redwood","scientific":"Metasequoia glyptostroboides","synonyms":[],"aliases":["dawn redwood","water fir"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"8","zoneNote":"Generally zones 4–8. A fast-growing deciduous conifer. Prefers summer moisture and dislikes extreme heat combined with drought.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy in the ground, less so in a pot. Insulate below about 20°F and keep a real winter rest.","dormancy":"Deciduous; must go dormant and cold. Do not keep it in a heated house.","winterizing":["Let foliage color and drop outdoors.","Protect the pot from severe cold; a cold frame or mulch collar works well.","Leafless trees may spend the coldest weeks in an unheated space if it stays cold and the pot does not dry out."],"wateringWinter":"Do not let the pot dry out completely. Keep it on the slightly moist side, with drainage.","lightWinter":"Low light is fine while leafless and cold.","repotWhen":"Late winter to early spring, as buds swell","repotCue":"Buds swelling, before the flush","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young — they grow extremely fast; every 2–3 years when mature","repotNotes":"Open, moisture-retentive mix. Be ready to repot more often than a pine. Spring only in the North.","rootPruning":"Fairly hard on a vigorous tree in spring. Recovery is usually rapid.","structuralPruning":"Late winter is ideal because the opposite branching is easy to read. They back-bud well but grow so fast that you must stay ahead of long internodes.","pinching":"Pinch or cut new growth often through the growing season or the tree will become coarse.","wiring":"After leaf-drop or just before the flush. Young branches are flexible; check wires often because thickening is fast.","fertilizing":"Hungry in summer. Feed regularly, then stop by late summer.","pests":"Mites in dry heat, and occasional fungal issues in stagnant air. Drought plus heat causes scorch.","leaf":{"group":"needle","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Soft, feathery, deciduous needles on opposite branchlets","evergreen":false,"features":"The key ID: branchlets and leaves are opposite, unlike bald cypress, which is alternate. Needles are soft, linear, and drop in autumn, often a warm russet. The trunk is straight and tapered, with shredding bark. A living fossil, once known only from fossils until it was found in China in the 1940s."},"facts":["Dawn redwood was known only from fossils until living trees were discovered in China in the mid-20th century — a botanical celebrity.","Opposite branching is the reliable way to tell it from bald cypress in summer or winter.","In the ground it can become a very large tree in a few decades; in a pot, frequent pruning and more frequent repotting are the price of that vigor."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Foliage often turns a rich apricot or russet before falling. Structure is then easy to wire.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"larix-kaempferi","common":"Japanese larch","scientific":"Larix kaempferi","synonyms":["Larix leptolepis"],"aliases":["Japanese larch","karamatsu"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"7","zoneNote":"Japanese larch is generally zones 4–7; European larch (Larix decidua) is often listed 2–6 and wants even more winter cold. Larches are poor trees for warm, mild-winter climates.","rootMinF":5,"protectBelowF":15,"bringInBelowF":null,"potNote":"Very hardy, but still protect a small pot in severe cold and from winter drought. They must stay cold in winter — a warm garage is worse than a well-mulched bench in the cold.","dormancy":"Obligate cold dormancy. Needs a real winter. In a mild, almost frost-free climate it often declines. Do not bring it into a heated house.","winterizing":["Leave it outdoors. Let it drop its needles and stay cold.","Insulate the pot for deep cold, and keep wind from drying the root ball.","Do not store it in a warm indoor room or a garage that regularly climbs into the 50s°F."],"wateringWinter":"Check on mild days; do not let the pot become dust-dry. Once leafless it uses less water, but it is not a cactus.","lightWinter":"Full light is fine; leafless cold trees also tolerate less light if they stay truly cold.","repotWhen":"Early spring, just as buds swell","repotCue":"The small knobby buds swell and show green — act then, before needles burst","repotMonths":[3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining but not desert-dry mix; they like moisture with air. Recovers well from spring root work. Do not repot in autumn.","rootPruning":"Fairly assertive on a healthy tree in early spring.","structuralPruning":"Late winter, when the silhouette is clear. Larches back-bud reasonably well and are excellent for informal, slightly wild styles.","pinching":"Shorten new long shoots in late spring and summer. Spur shoots (short needle tufts) are left to form the foliage pads.","wiring":"After needle-drop or in very early spring. Young branches are flexible; older ones snap if you rush, especially in deep cold.","fertilizing":"Regular in the growing season; stop by late summer so the tree hardens and colors well.","pests":"Larch casebearer, adelgids, and sawfly in some regions. Heat and drought are the cultural enemies, especially in midsummer.","leaf":{"group":"needle","arrangement":"tufted","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Soft deciduous needles in tufts on short spurs, single on long shoots","evergreen":false,"features":"Needles are soft, bright green, and drop in autumn after turning gold. On older twigs they sit in dense tufts or rosettes on short spurs; on new long shoots they are single and spiral. Cones are small and, on Japanese larch, often slightly reflexed at the scales. Never evergreen."},"facts":["Larch is one of the few deciduous pines-or-near-pines used in bonsai, with a golden autumn display and a spare winter form.","Japanese and European larch are both used; care is similar, though European larch is often considered slightly more cold-demanding.","Those tufted spurs are the ID mark — cedar (Cedrus) has similar tufts but is evergreen."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Prime repotting cue: buds swell. In very cold gardens wait until the pot can thaw and stay workable.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Needles turn a clear gold, then drop. A fine month to wire and to set up winter protection.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"ginkgo-biloba","common":"Ginkgo","scientific":"Ginkgo biloba","synonyms":[],"aliases":["maidenhair tree","ginkgo"],"family":"Ginkgoaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"8","zoneNote":"Generally zones 4–8, sometimes listed to 3 or 9 depending on the clone. Very cold-hardy in the ground, but a pot still needs insulation in severe winters. Male trees are preferred; females drop messy, foul-smelling fruit.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Protect the pot below about 20°F. Needs a real winter rest. Late to leaf out in spring, which is normal — do not assume it is dead in April.","dormancy":"Deciduous and fully hardy. Must rest in the cold. Do not keep it warm and indoor all winter.","winterizing":["Let the golden leaves drop outdoors.","Insulate the pot before severe freezes.","A cold, unheated space is acceptable once leafless.","Keep the root ball from drying out completely."],"wateringWinter":"Sparse but not bone-dry.","lightWinter":"Low light is fine while leafless and cold. Full sun once it leafs out.","repotWhen":"Early spring, just as buds swell — which may be later than maples","repotCue":"Buds swelling; the tree is often later than other deciduous species, so wait for its cue, not the calendar alone","repotMonths":[3,4],"repotFreq":"Every 2–3 years, or when roots pack the pot; not as frantic as a dawn redwood","repotNotes":"Well-draining deciduous mix. Roots can be thick and fleshy; work carefully and do not let them dry on the bench. Spring only.","rootPruning":"Moderate. Do not be as drastic as on a trident maple if the tree is not vigorous.","structuralPruning":"After leaf-drop or in late winter. Ginkgo has a somewhat stiff, upright branching habit and does not always ramify as finely as elm; design with that character. Thick branches do not always back-bud as freely as a maple.","pinching":"Shorten extending shoots in the growing season. Leaves are large on young plants and reduce only somewhat.","wiring":"Best when leafless. Branches can be brittle; bend slowly. Clip-and-grow often does more than wire on older wood.","fertilizing":"Regular in the growing season; stop by late summer for good autumn color and hardening.","pests":"Relatively few serious pests. The main issues are broken branches from clumsy wiring, and female fruit if you have a female tree.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"fan","lobes":"","margin":"wavy","shape":"Unique fan-shaped leaf, often notched in the middle, with forking (dichotomous) veins and no midrib","evergreen":false,"features":"Nothing else in the library looks like this: a fan- or duck-foot-shaped leaf with veins that fork and run to the margin, usually 1–3 inches on bonsai. Alternate on the shoot, often clustered on short spurs. Brilliant gold in autumn, then the leaves often drop all at once."},"facts":["Ginkgo is a living fossil, the last species of a group that flourished in the age of dinosaurs.","Male trees are almost always chosen for bonsai and street planting; female fruit smells strongly of butyric acid when it drops.","Autumn color is a clear, even gold, and the leaves often fall in a short period, as if on cue."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Often still bare when maples have already leafed out — wait for swelling buds before you repot or panic.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"The famous gold. After the leaves drop, usually quite suddenly, you can wire and set winter protection.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"fagus-sylvatica","common":"European beech","scientific":"Fagus sylvatica","synonyms":[],"aliases":["beech","European beech","Japanese beech"],"family":"Fagaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"7","zoneNote":"European beech is generally zones 4–7 and dislikes hot, dry summers. Japanese beech (Fagus crenata), also a classic bonsai, is often listed around zones 4–8 and is cared for in much the same way.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but thin bark and fine roots hate a frozen-dry pot and a late frost on new leaves. Protect below about 20°F. Needs a real winter rest.","dormancy":"Fully deciduous (though young trees may hold copper leaves, like many beeches). Must stay cold in winter.","winterizing":["Leave it outdoors to go dormant. Many beeches hold dried, coppery leaves on the branches until spring — that is normal.","Insulate the pot and break the wind.","Protect swelling spring buds and tender new leaves from a late frost, which can burn a whole flush."],"wateringWinter":"Do not let the fine roots dry out. Beech is less drought-tolerant than oak or pine, even in winter.","lightWinter":"Low light is fine while dormant. In leaf, give bright light with some afternoon shade in hot climates.","repotWhen":"Early spring, just as buds swell","repotCue":"Buds swelling — long, pointed buds are easy to see — before they open","repotMonths":[3,4],"repotFreq":"Every 2–3 years; be conservative if the tree is weak","repotNotes":"They have fine, somewhat sensitive roots. Do not bareroot a beech as a matter of course, and do not let roots dry during the work. Moist, well-aerated deciduous mix. Avoid autumn repotting.","rootPruning":"Moderate and careful. Leave more fine roots than you might on an elm.","structuralPruning":"Late summer or after leaf-drop. Beech does not always back-bud as freely on old, bare wood as elm does, so do not strip inner branches of all foliage. The smooth, tight bark is easily spoiled by clumsy cuts or sun-scald on thin-barked young trunks.","pinching":"Shorten the spring flush after it extends, leaving a couple of leaves on each shoot. Full defoliation is risky and usually avoided.","wiring":"After leaf-drop, very carefully: bark is thin and marks for years, and branches can snap. Use gentle bends and protect with raffia if needed.","fertilizing":"Moderate, not heavy, from late spring through mid-summer. Stop in late summer. They are not greedy, and overfeeding makes coarse leaves.","pests":"Aphids, scale, beech scale/bark disease in some regions, caterpillars, and scorch from heat or a dry pot. Late frost is a seasonal hazard.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"wavy","shape":"Ovate to elliptic with a wavy, almost entire margin and a pointed tip","evergreen":false,"features":"Alternate, simple leaves with very even, almost parallel side veins and a smooth to slightly toothed, wavy edge. Long, slender, pointed buds in winter are a clear ID. Bark is smooth and steel-gray on European beech. Japanese beech (F. crenata) is similar, with slightly more toothed leaves in some trees. Young trees often hold russet leaves through winter."},"facts":["The long, pointed winter buds are as useful an ID mark as the leaves.","Japanese beech (Fagus crenata) is the classic beech of Japanese bonsai; care is essentially the same as for European beech.","Many beeches keep their dead, copper-colored leaves until spring, a trait called marcescence, especially on younger or lower branches."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"New leaves are tender — a late frost can blacken them. Have a cover ready. Repot only as buds swell, and keep roots moist during the work.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Leaves turn gold or copper. After they color or drop (or dry in place), study the structure and wire very gently.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"carpinus-betulus","common":"European / Japanese hornbeam","scientific":"Carpinus betulus","synonyms":[],"aliases":["hornbeam","European hornbeam","Japanese hornbeam","Carpinus japonica"],"family":"Betulaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"8","zoneNote":"European hornbeam (C. betulus) is generally zones 4–8. Japanese hornbeam (C. japonica) is cared for almost identically and is usually listed in a similar range (about 4–8). Both are classic deciduous bonsai.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but insulate a shallow pot below about 20°F. Needs a cold winter rest. Fine twigs are tough, but new leaves can be nipped by a late frost.","dormancy":"Fully deciduous (young trees may hold some dry leaves). Must stay cold in winter.","winterizing":["Harden and drop leaves outdoors.","Protect the pot from severe freezes; a cold frame or mulch collar is plenty in most of the U.S.","A cold unheated space is acceptable once leafless.","Protect opening buds from a late frost in spring."],"wateringWinter":"Do not let the pot dry out completely. Hornbeams like even moisture year-round, with less in winter.","lightWinter":"Low light is fine while leafless and cold. In leaf, full sun to light afternoon shade in hot climates.","repotWhen":"Late winter to early spring","repotCue":"When buds swell, before they break","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"They recover well from spring root work. Standard deciduous mix with good drainage and some moisture-holding capacity. Avoid autumn repotting in the North.","rootPruning":"Fairly assertive on a healthy tree in spring. They often form a nice, compact root system and good nebari.","structuralPruning":"Late winter or after leaf-drop, when the fine ramification is easy to see. Hornbeams back-bud well and can be built with clip-and-grow.","pinching":"Shorten the spring flush after one or two internodes on strong outer shoots. They ramify readily. Full defoliation is only for vigorous trees, if at all.","wiring":"After leaf-drop. Wood is a bit flexible when young. Check wires in spring; they thicken steadily. The fluted, muscular trunk is a design feature — do not hide it.","fertilizing":"Regular in the growing season; taper or stop by late summer. Wait after a repot.","pests":"Aphids, caterpillars, and occasional leaf spot. Scorch in a hot, dry, windy site if the pot dries.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"double-serrate","shape":"Ovate, corrugated, with a doubly toothed margin and prominent parallel veins","evergreen":false,"features":"Alternate, simple leaves with a clearly corrugated (pleated) surface and very regular, parallel side veins running to sharp double teeth. Japanese hornbeam (C. japonica) is similar, often with slightly more elongated, prominently veined leaves. Winter buds are shorter and more angular than a beech’s long pointed buds. Bark becomes fluted and sinewy with age."},"facts":["The name hornbeam refers to the very hard wood, once used for yokes and implements.","Japanese hornbeam (Carpinus japonica) is a close cousin; use this entry for either, and expect the same seasonal work.","Old trunks become beautifully fluted, which is much of their character as bonsai."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Clear yellow autumn color on many trees. After leaf-drop, wire and read the ramification.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"carpinus-coreana","common":"Korean hornbeam","scientific":"Carpinus coreana","synonyms":["Carpinus turczaninowii","Carpinus turczaninowii var. coreana"],"aliases":["Korean hornbeam","Carpinus turczaninowii"],"family":"Betulaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"8","zoneNote":"Generally listed around zones 4–8 or 5–8. A prized bonsai hornbeam for small leaves, tight ramification, and handsome bark. Naming varies (C. coreana vs. C. turczaninowii).","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Same practical pot protection as other hornbeams: insulate below about 20°F, and give a real winter rest.","dormancy":"Deciduous. Requires a cold winter. Do not overwinter in a heated house.","winterizing":["Let it go dormant outdoors.","Protect the pot from severe cold.","Cold unheated storage is fine once leafless.","Guard new spring leaves from a late frost."],"wateringWinter":"Even, modest moisture; never bone-dry.","lightWinter":"Low light while leafless and cold; sun once in leaf, with some afternoon shade in hot regions.","repotWhen":"Late winter to early spring","repotCue":"Buds swelling, before they open","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–4 years when mature","repotNotes":"Standard deciduous mix. Recovers well in spring. A favorite for developing fine nebari with regular, careful repotting.","rootPruning":"Moderate to fairly firm on a healthy spring tree.","structuralPruning":"After leaf-drop or late winter. It ramifies exceptionally well and is often styled with a very fine, twiggy canopy.","pinching":"Shorten flushes during the growing season to keep internodes short. This species rewards frequent, light work.","wiring":"After leaf-drop. Check wires; it can thicken well. The bark — often a patchy gray-tan that becomes more interesting with age — is part of the appeal, so avoid wire scars where you can.","fertilizing":"Regular in the growing season; stop by late summer.","pests":"Aphids and caterpillars, plus scorch if a small pot dries in heat.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"double-serrate","shape":"Smaller ovate hornbeam leaf, corrugated, doubly toothed, with straight parallel veins","evergreen":false,"features":"Like other hornbeams: alternate, pleated leaves with parallel veins and double teeth, but usually smaller and more refined in this species. Twigs are fine. Bark is often a mottled gray or tan and becomes very attractive on older trunks. Autumn color is typically yellow to orange."},"facts":["Often considered the most refined hornbeam for bonsai, with naturally small leaves and tight twigs.","You will also see it labeled Carpinus turczaninowii; the horticultural care is the same.","It is a frequent choice for shohin and medium-size deciduous trees because it ramifies without becoming coarse."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Yellow to orange fall color, then a very fine winter silhouette — a good wiring month after leaf-drop.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"zelkova-serrata","common":"Japanese zelkova","scientific":"Zelkova serrata","synonyms":[],"aliases":["keyaki","Japanese zelkova","Japanese elm"],"family":"Ulmaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Typically zones 5–8, sometimes listed to 9. A classic broom-style deciduous tree in Japanese bonsai. Related to elms but not a true Ulmus.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect pots below the low 20s°F. Needs a cold winter rest. In zone 5, a sheltered or framed winter is prudent.","dormancy":"Deciduous. Must rest in the cold. Do not keep it in a warm house all winter.","winterizing":["Let leaves color and drop outdoors.","Insulate the pot and block drying wind before hard, regular freezes.","A cold unheated space is acceptable when leafless.","Protect early spring leaves from a late frost."],"wateringWinter":"Modest; never bone-dry.","lightWinter":"Low light while leafless and cold; full sun to light shade in the growing season (some afternoon shade in hot, dry sites).","repotWhen":"Late winter to early spring","repotCue":"Buds swelling, before they break","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Recovers well from spring root work. Standard deciduous mix. Avoid autumn repotting in the North.","rootPruning":"Fairly assertive on a healthy spring tree. Good nebari is part of a formal broom design and is built over many repots.","structuralPruning":"The classic form is a broom (hokidachi): a straight trunk and a fan of fine twigs. Build that with clip-and-grow after the first scaffold is set. Heavy cuts in late winter or after a flush. It back-buds well.","pinching":"Shorten new shoots repeatedly through the growing season to build the fine umbrella of twigs. Partial defoliation on vigorous trees in mid-summer is sometimes used.","wiring":"Mostly a clip-and-grow tree, especially in broom style. Light wiring after leaf-drop can place a branch, but scars show on the smooth bark.","fertilizing":"Regular in the growing season; taper late summer for good fall color and hardening.","pests":"Aphids, leaf beetles, spider mites in dry heat, and occasional Dutch elm–related concerns (zelkova is generally more resistant than American elm, but not invulnerable). Scorch if the pot dries.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Ovate to lance-ovate with a coarsely, evenly toothed margin and a longish tip","evergreen":false,"features":"Alternate, simple leaves with many sharp, regular teeth (more neatly ‘saw-toothed’ than a typical Chinese elm) and a slightly rough feel. The base is usually more symmetrical than Chinese elm. Bark on older trunks is smooth and gray, later exfoliating into a mottled, attractive pattern. Excellent yellow, orange, or russet autumn color."},"facts":["Keyaki is an important timber and temple tree in Japan, and one of the signature species for broom-style bonsai.","It is related to elms (Ulmaceae) but is not a true elm; the clean, even teeth and often smoother young bark help separate it from Chinese elm.","A well-ramified zelkova in winter, with every fine twig in place, is a traditional show piece."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Pinch early; this is how a broom canopy stays fine rather than coarse.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Often brilliant autumn color. After leaf-drop, the winter silhouette tells you whether last summer’s pinching was tight enough.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"cotoneaster-horizontalis","common":"Cotoneaster","scientific":"Cotoneaster horizontalis","synonyms":[],"aliases":["rock cotoneaster","cotoneaster"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"7","zoneNote":"C. horizontalis is often listed for zones 5–7 (sometimes 4–7). Other cotoneasters used in bonsai vary; some are a little hardier or more evergreen in mild winters. Confirm your plant, but pot protection is similar.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect shallow pots below the low 20s°F. Needs a winter rest. In a mild climate it may hold many leaves.","dormancy":"Deciduous to semi-evergreen depending on climate and species. Give it a cold outdoor or cold-frame winter, not a heated room.","winterizing":["Leave it out to harden.","Insulate the pot and break the wind before hard regular freezes.","Berries may persist into winter and are part of the display — protect the plant, not only the fruit.","Do not overwinter in a warm house."],"wateringWinter":"Modest; do not let it dry out completely, especially if it is holding leaves or berries.","lightWinter":"Good light if it holds leaves; low light is acceptable if fully dormant and leafless.","repotWhen":"Late winter to early spring","repotCue":"Buds swelling, before strong new growth","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining mix; they dislike a sour, wet pot in winter. Recovers reasonably well in spring. Watch for the stiff, herringbone twigs when you work the tree out of the pot.","rootPruning":"Moderate, at spring repotting.","structuralPruning":"Late winter, or after flowering. The natural herringbone branching is a design feature of C. horizontalis — you often edit it rather than fight it. It does back-bud, but very old, bare wood is less obliging than an elm.","pinching":"Shorten long shoots after the spring flush and again if needed, leaving short spurs that will flower and fruit.","wiring":"Young wood can be wired in late winter. Older wood is stiff and can snap. Thorns are absent or minor compared with pyracantha, but twigs are still twiggy and sharp-ish.","fertilizing":"Moderate in the growing season; too much nitrogen means lush growth and fewer flowers and berries. Taper late summer.","pests":"Aphids, fire blight (a rosaceous risk — avoid wet, lush, overfed growth), scale, and spider mites in dry heat. Birds will take berries, which is charming until it isn’t.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Small, oval to rounded leaves, usually with a smooth margin","evergreen":false,"features":"Alternate, small (often ¼–½ inch) oval leaves on stiff, spreading, herringbone-like twigs (especially C. horizontalis). Margins are typically entire. Tiny white or pinkish flowers in spring, then red or orange berries. May be semi-evergreen in a mild winter. No true thorns like firethorn, though dead twig tips can feel sharp."},"facts":["The herringbone branching of rock cotoneaster is so distinctive it is often left as a design theme rather than fully ‘tamed.’","Berries are a big part of the winter interest and will hang on after leaf-drop in many years.","Several cotoneaster species are used in bonsai; this entry covers the common rock cotoneaster and close cousins with only small adjustments."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Small flowers appear; avoid heavy pruning just as it blooms if you want a berry crop.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Berries often color the winter silhouette. Protection should already be in place.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"pyracantha-coccinea","common":"Firethorn","scientific":"Pyracantha coccinea","synonyms":[],"aliases":["firethorn","pyracantha"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"Typically zones 6–9, with some variation by cultivar. Evergreen to semi-evergreen. Sharp thorns — handle with gloves.","rootMinF":15,"protectBelowF":25,"bringInBelowF":null,"potNote":"Protect pots below the mid-20s°F. Foliage can winter-burn in wind and sun. Give a cold rest, not a heated room.","dormancy":"Evergreen or nearly so, but it still wants a cool to cold winter. Do not keep it in a warm dark house.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot and shield foliage from drying winter wind.","Berries may hang into winter; they are part of the show.","In zone 6, pot protection is especially important."],"wateringWinter":"Evergreen foliage still transpires. Water when the mix begins to dry, and do not let a frozen wind dry the pot out.","lightWinter":"Good light. Shelter from harsh, drying winter sun in exposed sites.","repotWhen":"Late winter to early spring, or after flowering","repotCue":"Just as growth begins, or shortly after the spring bloom if you prefer to protect flowers","repotMonths":[3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining mix. Wear gloves — the thorns are no joke. Spring is the conservative window.","rootPruning":"Moderate, at spring repotting.","structuralPruning":"After flowering if you want to keep the current berry crop forming; otherwise late winter. It back-buds reasonably well. Leave some of the short flowering wood.","pinching":"Shorten long vegetative shoots, leaving fruiting spurs. Respect the thorns.","wiring":"Awkward because of the thorns; many growers use clip-and-grow plus a little careful wire on younger, less vicious shoots. Wear eye protection.","fertilizing":"Moderate. Heavy nitrogen favors leaf over flower and fruit. Feed after bloom through mid-summer, then taper.","pests":"Fire blight, aphids, scale, and scab or sooty mold. Good airflow and restrained nitrogen help. Birds love the berries.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Small, elliptic to oblong, finely toothed, glossy evergreen leaves","evergreen":true,"features":"Alternate, small, usually finely serrate, glossy leaves, evergreen or nearly so. Sharp thorns (actually stiff modified shoots) in the leaf axils. Clusters of small white spring flowers, then brilliant orange, red, or yellow berries. Compare cotoneaster, which lacks true thorns and often has entire leaf margins."},"facts":["The name Pyracantha means ‘fire thorn,’ a nod to the berry color and the genuine thorns.","Berries can persist well into winter and are one of the main reasons to grow it as bonsai.","Handle and wire with real care; the thorns can go through a glove if you are careless."],"calendar":{"1":"Evergreen — check water, protect the pot, and enjoy any remaining berries. Keep it cold, not in a warm room.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Flowering begins in many climates. Hold off heavy pruning if you want a full berry set.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Berries color up. Reduce fertilizer and prepare wind protection for the evergreen foliage.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"malus","common":"Crabapple","scientific":"Malus","synonyms":["Malus halliana","Malus sieboldii","Malus cerasifera"],"aliases":["crabapple","crab apple","flowering crab"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"8","zoneNote":"Most crabapples used in bonsai fall in zones 4–8, with wide cultivar variation. They need a genuine winter chill to bloom well.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Protect pots below about 20°F. A warm indoor winter usually costs you the next spring’s flower display and weakens the tree.","dormancy":"Deciduous. Requires a cold rest and a period of chilling for reliable bloom. Keep it outdoors or in a cold frame.","winterizing":["Let it drop leaves and stay cold outside or in a cold frame.","Insulate the pot before severe freezes.","Do not store it in a heated house.","Protect opening flower buds in spring from a late frost, which can wipe out a year’s bloom."],"wateringWinter":"Modest; never bone-dry. Increase as buds swell in spring.","lightWinter":"Low light is fine while leafless and cold. Full sun in the growing season for the best flowering.","repotWhen":"Late winter, just as buds swell, and preferably before they show a lot of color","repotCue":"Buds swelling, before flowers open — if the tree is already in tight bud, be gentle and timely","repotMonths":[2,3],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining deciduous mix. They often have vigorous roots. If the tree is about to bloom, a slightly more conservative root prune is kind, or repot immediately after flowering in a cool spring.","rootPruning":"Moderate to firm on a healthy tree, ideally just before or just after bloom, not in mid-flower if you can help it.","structuralPruning":"After flowering (you can see which spurs performed) or in late winter if you can ‘read’ the flower buds. Flowers form on short spurs and older wood — if you clip every spur, you get leaves, not blossoms.","pinching":"Shorten long vegetative (water) shoots after they extend, but leave fruiting spurs alone.","wiring":"After leaf-drop or after flowering. Young wood is flexible; older wood can split. Avoid wiring off flower buds by accident.","fertilizing":"Moderate. Too much nitrogen means fewer flowers. Feed after bloom, taper by late summer. A slightly lower-nitrogen feed supports flowering.","pests":"Aphids, apple scab, cedar-apple rust in some regions, borers on stressed trees, and fire blight. Good airflow and sanitation of fallen leaves help. Fruit can be left for display or reduced if the tree is weak.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Ovate, toothed leaves, sometimes slightly lobed on vigorous shoots","evergreen":false,"features":"Alternate, simple, serrate leaves, typically 1–3 inches, with a familiar apple-leaf look. Flowers are five-petaled, usually white, pink, or red, in spring, followed by small persistent fruit. Winter twigs show fat mixed buds and short fruiting spurs. Some vigorous shoots may be slightly lobed."},"facts":["Crabapples are among the most rewarding flowering and fruiting bonsai if they get a real winter.","The difference between a tree that blooms and one that only grows leaves is usually chill, sun, and leaving the fruiting spurs alone.","Many species and hybrids are used (Malus halliana, M. sieboldii, and others); seasonal care is essentially the same."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Repot as buds swell, before they open if you can. A late frost once flowers are out can end the show — have a cover ready.","4":"Peak bloom in many parts of the U.S. After flowers fade, prune and, if you postponed it, repot.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Fruit colors on many cultivars. Do not fertilize hard now; let the tree harden.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"chaenomeles-speciosa","common":"Flowering quince","scientific":"Chaenomeles speciosa","synonyms":["Chaenomeles japonica"],"aliases":["flowering quince","Japanese quince","chojubai"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"9","zoneNote":"C. speciosa is often listed zones 5–9; C. japonica similar, sometimes 4–8. The famous ‘Chojubai’ dwarf quinces are Japanese favorites and are treated the same way, with even more emphasis on a cold rest for bloom.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but protect pots below about 20°F. Must stay cold in winter or flowering suffers. Flowers can open in very late winter — protect those early blooms from a hard freeze.","dormancy":"Deciduous (or nearly so). Needs a cold rest. One of the earliest trees to bloom, sometimes on bare wood in late winter.","winterizing":["Keep it cold outdoors or in a cold frame.","Insulate the pot before severe freezes.","Watch late-winter flowers: a very hard night can brown open blooms, even if the tree is unharmed.","Do not overwinter in a heated room."],"wateringWinter":"Modest; increase slightly as buds swell and flowers open.","lightWinter":"Good light as buds move. Leafless cold trees can take lower light, but a bright cold frame helps early bloom.","repotWhen":"After flowering, or in very late winter just as growth begins if the tree is not yet in bloom","repotCue":"When flowers fade and vegetative buds begin to move","repotMonths":[3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining mix. Roots can be dense and a bit brittle. After-bloom spring work is the usual, conservative choice. Chojubai in small pots may need more frequent attention.","rootPruning":"Moderate, after bloom or at the start of growth.","structuralPruning":"After flowering. Flowers are borne on older short wood and spurs, so a late-summer chop can reduce next year’s bloom. Thin crossing twigs and leave a network of older flowering wood.","pinching":"Shorten long vegetative shoots after they have extended, without stripping the short flowering spurs.","wiring":"After flowering or after leaf-drop. Branches can be stiff and slightly brittle, and many plants are thorny. Clip-and-grow is often easier.","fertilizing":"After bloom through mid-summer, then taper. Excess nitrogen favors rank growth over flowers.","pests":"Aphids, scale, and fire blight (go easy on nitrogen and avoid working a wet, succulent tree). Chlorosis in very alkaline soils.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Ovate, finely toothed, often somewhat glossy leaves, usually with stipules at the base","evergreen":false,"features":"Alternate, simple, finely serrate leaves, often 1–3 inches, slightly leathery or glossy, with noticeable stipules. Many plants have thorns. Flowers are typically red, pink, white, or orange, often on bare wood in late winter or early spring, before or with the leaves. Fruit is a small, hard quince. Compare Chinese quince (Pseudocydonia), which has larger leaves, usually no thorns, and flaking bark."},"facts":["Flowering quince often blooms on bare branches, a much-loved late-winter sight.","Chojubai, a dwarf Japanese flowering quince group, is a specialist bonsai subject and can flower more than once in a year when it is happy.","It is not the same as the fruiting Chinese quince, Pseudocydonia sinensis, which is grown more for bark and fruit."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"In a mild spell, flowers may already be opening. Keep the pot protected on hard nights and delay any hard work until you can see how bloom is going.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"After flowers fade, prune and repot. This is the main structural window.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Leaf-drop reveals next year’s flowering spurs. A light wiring and cleanup month, not a heavy pruning month.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"pseudocydonia-sinensis","common":"Chinese quince","scientific":"Pseudocydonia sinensis","synonyms":["Chaenomeles sinensis","Cydonia sinensis"],"aliases":["Chinese quince","kinin"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Generally zones 5–8. Grown in bonsai for its flaking, multi-colored bark, autumn color, and large yellow fruit.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect pots below the low 20s°F. Needs a cold winter. Fruit left on a small tree can be heavy and exhausting — reduce if the tree is weak.","dormancy":"Deciduous. Cold outdoor rest required.","winterizing":["Let it drop leaves outdoors and stay cold.","Insulate the pot before severe freezes.","Do not overwinter in a heated house."],"wateringWinter":"Modest; never bone-dry.","lightWinter":"Low light while leafless and cold; full sun in the growing season.","repotWhen":"Late winter to early spring","repotCue":"Buds swelling, before they break","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining deciduous mix. Spring work is safest. Large roots can develop; keep a good nebari in mind.","rootPruning":"Moderate to fairly firm on a healthy spring tree.","structuralPruning":"Late winter or after leaf-drop. It does not always ramify as finely as an elm; design for a strong trunk, beautiful bark, and well-spaced branches. Flowers and fruit form on older wood — do not strip every short shoot.","pinching":"Shorten long shoots after they extend. Leave some short laterals for flower and fruit.","wiring":"After leaf-drop. Branches can be stiff; bend gradually so you do not spoil the bark.","fertilizing":"Regular in the growing season; taper late summer. If the tree is carrying large fruit, it may need slightly more consistent feeding and water, or you can thin the fruit.","pests":"Aphids, scale, and the usual rosaceous issues including possible fire blight. Watch chlorosis in very alkaline conditions.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Larger elliptic leaves with a finely toothed margin","evergreen":false,"features":"Alternate, simple, serrate leaves, usually larger and more elliptic than flowering quince. Typically unarmed (no thorns). The show is the bark: it flakes in patches of tan, gray, green, and rust on older trunks. Pink or white flowers in spring, then a large, fragrant yellow quince. Excellent autumn color."},"facts":["The mottled, exfoliating bark is the main reason growers put up with the large leaves and fruit.","It used to be grouped with quinces (Chaenomeles or Cydonia) and is now in its own genus, Pseudocydonia.","A single fruit can look oversized on a small bonsai; thinning fruit is both aesthetic and kinder to the tree."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Flowers, then new leaves. Repot as buds swell if you did not do it in late winter.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Fruit ripens yellow and fragrant, and the leaves often color well. After leaf-drop the bark is on full display.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"wisteria-floribunda","common":"Japanese wisteria","scientific":"Wisteria floribunda","synonyms":[],"aliases":["wisteria","Japanese wisteria","Chinese wisteria"],"family":"Fabaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"9","zoneNote":"W. floribunda is generally zones 5–9; Chinese wisteria (W. sinensis) is similar, often 5–8. Both need a winter chill to bloom reliably. In the landscape they can be invasive in parts of the U.S. — contain seed and vigorous shoots.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect pots below the low 20s°F. A warm indoor winter usually means lots of vine and few racemes. Roots are vigorous and the pot dries fast in summer.","dormancy":"Deciduous. Needs a cold rest and a period of chill for good flowering. Keep it outside or in a cold frame.","winterizing":["Let it drop leaves and stay cold outdoors or in a cold frame.","Insulate the pot before severe freezes.","Do not overwinter in a heated house if you want flowers.","Protect emerging flower racemes from a late frost in spring."],"wateringWinter":"Modest; the thick roots should not dry out completely. Water freely once it is in full summer growth.","lightWinter":"Low light is fine while leafless and cold. Full sun in the growing season is important for bloom.","repotWhen":"Early spring, as buds swell, or immediately after flowering","repotCue":"Buds swelling, or right after the flower display if you prefer not to disturb racemes","repotMonths":[3,4],"repotFreq":"Every 1–2 years — roots are aggressive and will circle and lift the tree","repotNotes":"A deepgish, well-draining pot and a strong mix help. Be ready for a dense, muscular root system. After-flower or pre-flower spring work is standard. Do not let roots dry during the job.","rootPruning":"Firm, every year or two, or the pot becomes a solid root mass. Keep enough coarse roots for stability; wisteria is a thirsty plant in summer.","structuralPruning":"A vine by nature: choose a trunk, then shorten long runners repeatedly. Flower buds form on short spurs from older wood. The main prune is after flowering and again in summer on the long vegetative whips. If you cut all the old spurs, you delay bloom for a year or more.","pinching":"Pinch long leafy shoots through summer, leaving the short flowering spurs. This is the heart of wisteria bonsai maintenance.","wiring":"Younger wood can be wired to set a trunk line or a branch, preferably when leafless. Older vine wood is stiff and can split. Guy wires and pruning often do more than tight coils.","fertilizing":"Go easy on nitrogen, or you will get a jungle and no flowers. A modest, lower-nitrogen feed after bloom is usually enough. Do not feed heavily at the end of summer.","pests":"Aphids on soft tips, scale, and occasional caterpillars. The cultural problems are more common: no bloom (not enough sun, not enough chill, too much nitrogen, or all the spurs cut off), and a constantly drying pot in July.","leaf":{"group":"broad","arrangement":"alternate","compound":"pinnate","lobed":"none","lobes":"","margin":"entire","shape":"Pinnately compound leaves with typically 9–19 oval leaflets (Japanese) or often 7–13 (Chinese)","evergreen":false,"features":"Alternate, pinnately compound leaves — a long midrib with many entire, ovate leaflets. Japanese wisteria (W. floribunda) usually has more leaflets and longer, later flower racemes that open from the base; Chinese wisteria (W. sinensis) often has slightly fewer leaflets and racemes that open more nearly at once. Twining woody vines with hanging flower clusters in spring, before or with the leaves. Seed pods are velvety legumes. All parts are toxic if eaten."},"facts":["Japanese wisteria racemes can hang several feet long on garden plants; on bonsai they are shorter but still dramatic.","Chinese wisteria (Wisteria sinensis) is grown the same way; the two can be told apart by leaflet count, raceme habit, and the direction they twine.","Lack of flowers is almost always a training or chill issue, not a mystery disease — sun, a real winter, restrained nitrogen, and intact short spurs."],"calendar":{"1":"Deep dormancy. Check winter protection and water only enough to keep the root ball from drying completely. No fertilizer, no repotting.","2":"Still dormant. In milder climates, buds may begin to swell late in the month — that is the cue to prepare soil and tools for repotting. Keep protection in place during hard freezes.","3":"Main repotting and root-pruning window in most of the U.S., just as buds swell. Structural pruning can be done at the same time on healthy trees. Protect tender new leaves from a late freeze.","4":"Bloom month in much of the U.S., sometimes May. After flowers fade, prune and, if needed, repot. Then watch for long vegetative shoots and pinch them.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"A jungle of runners will appear if you do not pinch. This is normal — stay after it.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Autumn color on many deciduous species. After leaf-fall, the branch structure is easy to read — a good time for light wiring and planning winter protection. Reduce watering as growth stops.","11":"Leafless structure and any remaining seed pods are easy to read. Protection should be in place.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}},{"id":"olea-europaea","common":"Olive","scientific":"Olea europaea","synonyms":[],"aliases":["European olive","olive"],"family":"Oleaceae","place":"both","climate":"mediterranean","zoneMin":"8","zoneMax":"10","zoneNote":"Typically zones 8–10, sometimes 8a–11. Established landscape trees can survive brief dips around 15–20°F, but damage is common in the mid-teens, and a potted tree is less hardy. In most of the U.S. it wants a cool, bright, frost-protected winter.","rootMinF":25,"protectBelowF":32,"bringInBelowF":32,"potNote":"Move a potted olive to a frost-free, cool, bright place before a hard freeze. Many growers bring it in as nights settle in the upper 20s to around 32°F. Do not leave it out for a night in the teens. A warm living room all winter is better than a freeze, but a cool sunroom or garage with a window (mid-30s to 50s°F) is kinder.","dormancy":"No deep freeze dormancy, but it benefits from a cool winter rest with good light. Constant tropical heat is not required and can keep it growing weakly.","winterizing":["In zones 9–10, protect the pot and cover the tree for the occasional frost; a brief light frost may be tolerated, a hard freeze is not.","In colder zones, move it to a cool, bright, frost-free space before a hard freeze — often when nights dip to around freezing.","Cut back on water and stop fertilizer during this cool rest.","Give as much light as you can; a dark, warm garage is a poor home for an evergreen olive."],"wateringWinter":"Sparingly. Let the mix dry somewhat between waterings. A cold, wet olive is at risk of root trouble.","lightWinter":"Maximum light. A south window or a cool greenhouse is ideal.","repotWhen":"Early spring, as growth begins","repotCue":"When new shoots start to move, before summer heat","repotMonths":[3,4,5],"repotFreq":"Every 2–3 years, or when the very dense roots have packed the pot","repotNotes":"Very free-draining, mineral mix — olives hate stagnant moisture. Roots can be tight and fibrous. Spring, in warming conditions, is safest. Do not repot going into a dark winter.","rootPruning":"Moderate. They have dense, felt-like roots; open them up, but do not strip a weak tree bare. Leave enough to get it through a dry, bright summer.","structuralPruning":"Late winter or early spring, and again after a flush. Olives back-bud well, including on older wood, which is why old trunks look so convincing. Avoid very hard cuts just as you go into winter in a cold climate.","pinching":"Pinch or clip new shoots during the growing season to keep internodes short. They can be kept quite dense.","wiring":"Young branches are reasonably flexible in the growing season or early spring. Older olive wood is hard; use gentle bends, guy wires, and pruning. Protect the attractive bark.","fertilizing":"Regular from spring through mid-summer; taper late. Little or no winter feed during a cool rest.","pests":"Scale, olive knot (in some regions), spider mites indoors, and sooty mold on honeydew. The main cultural problem is a cold, wet pot or a dark winter.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Narrow, lanceolate, leathery leaves, gray-green above and silvery beneath","evergreen":true,"features":"Opposite, simple, evergreen leaves, typically 1–3 inches, lance-shaped, with a smooth margin. The undersides are distinctly silvery or scaly, a clear ID. Twigs are often slightly gray or pale. Small, fragrant, off-white flowers in spring or early summer may lead to fruit on outdoor trees in a long season. Trunks become gnarled and pitted with age."},"facts":["Olive trees can live for many centuries; old, hollow, sculpted trunks are part of why they make such characterful bonsai.","The silvery leaf underside is an adaptation to hot, bright Mediterranean light and is the quickest ID mark.","Fruit is possible on a bonsai that spends a long, sunny summer outdoors, but many trees are grown purely for foliage and trunk."],"calendar":{"1":"Cool, bright, frost-protected rest. An unheated room, garage with a window, or cold greenhouse in the mid-30s to 50s°F is ideal in cold climates. Water sparingly. No fertilizer.","2":"Still in cool rest. In zone 8–10, trees outdoors need protection from the occasional hard freeze. In colder zones, keep them in the cool overwintering spot.","3":"Usual repotting month as growth starts. Use a very draining mix and a warming, bright location after the work.","4":"Growth begins in earnest. Increase water. Wait a few weeks after a repot before fertilizing. Begin moving protected trees toward their summer sun, carefully.","5":"Active growth. Full sun is typically preferred. Fertilize regularly. Pinch long shoots to keep ramification tight.","6":"Full sun and a regular watering rhythm. A good month for pinching and, in mild climates, for flowers.","7":"Heat and drought are the main risks. Do not let the pot bake dry. A little afternoon shade can help in very hot inland climates. Keep up fertilizer on vigorous trees.","8":"Continue summer care. Taper fertilizer late in the month if you want growth to harden.","9":"Ease off nitrogen. In the North, start planning a cool winter rest. Still too early to lock the tree in a dark garage.","10":"Reduce water as growth slows. Move the tree to its cool winter quarters before a hard freeze — often when nights dip into the mid-30s to low 40s°F, depending on species.","11":"Cool rest underway. Bright light and chilly, frost-free nights are better than a warm living room. Water little.","12":"Hold the cool, bright rest. Check the pot on milder days so it never dries to dust."}},{"id":"punica-granatum","common":"Pomegranate","scientific":"Punica granatum","synonyms":[],"aliases":["pomegranate","dwarf pomegranate","Punica granatum ‘Nana’"],"family":"Lythraceae","place":"both","climate":"mediterranean","zoneMin":"8","zoneMax":"10","zoneNote":"Often listed zones 8–10, sometimes 7–10 for tougher clones. Landscape trees can be damaged in the teens °F. The dwarf ‘Nana’ is the usual bonsai form. In cold-winter regions it is deciduous and wants a cool, frost-protected rest.","rootMinF":22,"protectBelowF":30,"bringInBelowF":30,"potNote":"A potted pomegranate should not be left out for a hard freeze. Bring it to a cool, frost-free place as nights approach the high 20s to around 30°F. In zone 8–10, pot protection and a cover for the odd cold night may be enough. A warm indoor winter keeps it leafy but may reduce flowering.","dormancy":"Deciduous in a cool winter (the usual and healthier pattern for bloom); nearly evergreen only in very mild climates. A cool rest (roughly mid-30s to 50s°F) is better than a heated living room.","winterizing":["In cold zones, move to a cool, bright or even dimmer frost-free space when nights threaten a hard freeze, after it has begun to drop leaves.","In mild zones, protect the pot and cover for frost, and let it rest outdoors.","Reduce water. Stop fertilizer.","Do not keep a tree you want to flower in a constantly warm, dark room."],"wateringWinter":"Sparingly once leafless. Do not let the pot become dust, and do not keep it wet and cold.","lightWinter":"If it holds leaves, give bright light. If fully leafless and cool, light is less critical as long as it stays cold enough to rest.","repotWhen":"Late winter to early spring, as buds swell","repotCue":"Buds swelling, before strong new growth","repotMonths":[2,3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining mix; it likes sun and does not want a soggy pot. Spring is the conservative window. ‘Nana’ in small pots may need more frequent work.","rootPruning":"Moderate to fairly firm on a healthy spring tree.","structuralPruning":"Late winter, when the often slightly zigzag, twiggy structure is visible, or after the first flush. Flowers form on new growth of the season in many cases — a very hard late prune can delay bloom, but normal thinning does not. It back-buds reasonably well.","pinching":"Shorten long shoots after they extend, leaving some new growth to flower. After flowering, tidy the tree and reduce seed heads if the fruit is too heavy.","wiring":"When leafless, or early in the season. Younger branches are flexible; older wood can be stiff. The slightly erratic branching is part of its charm.","fertilizing":"Regular from late spring through mid-summer once growth is underway; taper late. A tree in cool winter rest gets no fertilizer.","pests":"Aphids on new growth, whitefly, scale, and occasionally leaf spot. Indoors, watch mites. Fruit may mummify or drop on a weak tree — thin it rather than force a heavy crop.","leaf":{"group":"broad","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Narrow oblong to lanceolate, glossy, smooth-edged leaves, often in opposite or slightly sub-opposite pairs","evergreen":false,"features":"Opposite or nearly opposite, simple, entire, glossy leaves, typically 1–3 inches (smaller on ‘Nana’), sometimes with a slightly wavy edge and a short petiole. New growth is often bronze or reddish. Flowers are tubular to bell-shaped, usually orange-red, in summer, followed by the familiar (or miniature) pomegranate fruit. Deciduous in a cool winter. Stems are often slightly angled or twiggy."},"facts":["The dwarf ‘Nana’ is the usual bonsai pomegranate and will bear small, decorative fruit in a sunny summer.","It has been grown around the Mediterranean and in Asia for thousands of years; the fruit is a traditional symbol of abundance.","A cool, leafless rest followed by a hot, sunny summer is the combination that usually produces the best flowers."],"calendar":{"1":"Cool, bright, frost-protected rest. An unheated room, garage with a window, or cold greenhouse in the mid-30s to 50s°F is ideal in cold climates. Water sparingly. No fertilizer.","2":"Still in cool rest. In zone 8–10, trees outdoors need protection from the occasional hard freeze. In colder zones, keep them in the cool overwintering spot.","3":"Repot as buds swell. In a mild climate growth starts early.","4":"Growth begins in earnest. Increase water. Wait a few weeks after a repot before fertilizing. Begin moving protected trees toward their summer sun, carefully.","5":"Active growth. Full sun is typically preferred. Fertilize regularly. Pinch long shoots to keep ramification tight.","6":"Often in flower in a sunny summer. Water faithfully once it is in full leaf; pots dry fast.","7":"Heat and drought are the main risks. Do not let the pot bake dry. A little afternoon shade can help in very hot inland climates. Keep up fertilizer on vigorous trees.","8":"Continue summer care. Taper fertilizer late in the month if you want growth to harden.","9":"Ease off nitrogen. In the North, start planning a cool winter rest. Still too early to lock the tree in a dark garage.","10":"Reduce water as growth slows. Move the tree to its cool winter quarters before a hard freeze — often when nights dip into the mid-30s to low 40s°F, depending on species.","11":"Should be in its cool rest in cold climates, often leafless or nearly so. Do not keep it in a hot room if you can give it a chilly, frost-free one.","12":"Hold the cool, bright rest. Check the pot on milder days so it never dries to dust."}},{"id":"chloroleucon-tortum","common":"Brazilian rain tree","scientific":"Chloroleucon tortum","synonyms":["Pithecellobium tortum","Mimosa torta"],"aliases":["Brazilian rain tree","BRT","Pithecellobium tortum"],"family":"Fabaceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"A tropical Brazilian tree. Outdoors year-round only in zones 10–11. Everywhere else it is a warm-season outdoor tree and a bright indoor winter tree.","rootMinF":50,"protectBelowF":55,"bringInBelowF":55,"potNote":"Bring in before nights in the low 50s°F. It is not frost-tolerant, and cool, wet roots in the 40s can set it back. Warmth and light are the winter theme.","dormancy":"No cold dormancy. Leaves may close at night (a nyctinastic movement) and the tree may rest a little in short days.","winterizing":["Indoors before nights in the low 50s°F.","Pest-check first (mites love indoor BRT).","The brightest light you can give, and stable warmth.","Expect some leaflet drop after the move if light drops sharply; improve light rather than overwatering."],"wateringWinter":"When the surface begins to dry. It likes even moisture in active growth and a bit less in a dim winter, but do not let it shrivel.","lightWinter":"Maximum light. This tree stretches quickly in a weak window.","repotWhen":"Late spring and summer, when nights are warm","repotCue":"Active growth and consistently warm weather","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years; it can be a vigorous rooter in warmth","repotNotes":"Free-draining tropical mix. Recovers well from root work in summer heat and humidity. Do not repot as you bring it into a dim house for winter.","rootPruning":"Fairly firm in the growing season on a healthy tree. The flaring, often twisted nebari is a signature — develop it on purpose at each repot.","structuralPruning":"During growth. It back-buds well and can be kept quite ramified. The naturally twisting trunk is a design gift; do not try to make it perfectly straight unless that is your aim.","pinching":"Pinch new shoots through the summer to keep the fine, compound foliage dense.","wiring":"Young branches are flexible in the growing season. Older wood hardens and twists. Protect the often-pale, interesting bark.","fertilizing":"Regularly in the growing season. Little or none in a low-light winter unless it is clearly growing under strong lights.","pests":"Spider mites are the classic problem, especially indoors — inspect the tiny leaflets often. Also scale and mealybugs. Dry indoor air makes mites worse.","leaf":{"group":"broad","arrangement":"alternate","compound":"bipinnate","lobed":"none","lobes":"","margin":"entire","shape":"Bipinnate leaves with many tiny leaflets that often fold closed at night","evergreen":true,"features":"Feathery, twice-compound (bipinnate) leaves with numerous small, entire leaflets. The leaves often close at night or when touched, a helpful ID. Small, typically whitish, puffball-like flowers may appear on a happy tree. The trunk is frequently twisted or corkscrew-like, with pale, sometimes flaking bark. Thorns may be present on some trees."},"facts":["The leaflets folding at night are the source of the ‘rain tree’ charm and a quick ID in a mixed collection.","It is still widely sold as Pithecellobium tortum; the current name for many of these trees is Chloroleucon tortum.","The naturally twisting trunk means even a young tree can look ancient with a little patience."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Peak growth. A fine month to style, pinch, and, if needed, repot. Watch for mites in dry heat.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"schefflera-arboricola","common":"Dwarf schefflera","scientific":"Schefflera arboricola","synonyms":["Heptapleurum arboricolum"],"aliases":["Hawaiian umbrella tree","dwarf umbrella tree","schefflera"],"family":"Araliaceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"Tropical; outdoor year-round only in zones 10–11. One of the most forgiving indoor bonsai, especially in lower light than Ficus prefers — though it still wants good light to stay compact.","rootMinF":45,"protectBelowF":50,"bringInBelowF":50,"potNote":"Bring in before nights near 50°F. Do not expose it to frost or to long spells in the 40s. An easy indoor winter tree.","dormancy":"No cold dormancy. Growth slows in short days.","winterizing":["Indoors before nights around 50°F.","Bright to medium-bright light; avoid icy drafts.","Water a little less in short days.","Wipe the large leaflets now and then so they can breathe and you can spot pests."],"wateringWinter":"When the top of the mix dries. It will forgive a missed watering better than a constantly soggy pot, but do not shrivel it.","lightWinter":"Bright light produces tighter growth. It will survive lower light than many tropicals, at the cost of longer internodes and larger leaves.","repotWhen":"Late spring and summer","repotCue":"Warmth and active growth","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining tropical mix. Very tolerant of root work in warmth. Aerial roots can be encouraged with humidity and are part of some designs. The current botanical name in many references is Heptapleurum arboricolum.","rootPruning":"Fairly assertive in summer on a healthy tree.","structuralPruning":"Year-round when growing. It back-buds, though sometimes slowly, on older wood. Large leaves mean it is often grown as a more tropical, slightly larger-scale tree, or as a clump.","pinching":"Remove or shorten extending shoots and, if needed, individual leaflets to reduce visual size. Some growers also trim leaflets.","wiring":"Younger stems are green and flexible; older stems lignify and can snap. Wrap or use guy wires for larger bends. Marks show on green bark.","fertilizing":"Regular in the growing season; light or none in a dim winter.","pests":"Spider mites, scale, and mealybugs, especially in dry indoor air. The broad leaflets make mites easy to see if you look underneath.","leaf":{"group":"broad","arrangement":"spiral","compound":"palmate-compound","lobed":"none","lobes":"","margin":"entire","shape":"Palmately compound leaves with usually 7–9 glossy, entire leaflets from one point, like an umbrella","evergreen":true,"features":"The umbrella is the ID: long petioles ending in a palmate whorl of typically 7–9 (sometimes fewer) leathery, smooth-edged leaflets. Alternate or spiral on the stem. Evergreen. New leaves unfurl from the center of the umbel. Variegated cultivars exist. No milky sap like Ficus."},"facts":["It is still almost always sold as Schefflera arboricola, though many botanists now use Heptapleurum arboricolum.","A favorite first indoor bonsai because it tolerates the mistakes that quickly kill a juniper kept in the house.","The ‘umbrella’ of leaflets is why it is called Hawaiian umbrella tree, even though it is native to Taiwan and nearby islands."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"bougainvillea-glabra","common":"Bougainvillea","scientific":"Bougainvillea glabra","synonyms":["Bougainvillea spectabilis"],"aliases":["bougainvillea","paper flower"],"family":"Nyctaginaceae","place":"indoor","climate":"tropical","zoneMin":"9","zoneMax":"11","zoneNote":"Generally zones 9–11 outdoors. In zone 9 it may still need protection from a hard frost. The colorful ‘flowers’ are actually bracts; true flowers are small and usually white or yellow in the center.","rootMinF":38,"protectBelowF":45,"bringInBelowF":45,"potNote":"Bring in before nights in the mid-40s°F. Damage occurs near freezing, and a potted plant is less hardy than a sheltered landscape vine in zone 9. It wants a bright, relatively dry winter rest rather than a warm, wet one.","dormancy":"No freeze dormancy, but it often drops some leaves and rests if kept cooler and drier in winter, which can actually help later blooming.","winterizing":["Indoors or into a frost-free greenhouse before mid-40s°F nights.","The brightest window you have, and cooler if possible (50s°F is fine).","Water less; a slightly dry rest is better than a soggy, dim one.","It may drop leaves — do not overwater in response."],"wateringWinter":"Infrequent. Let the mix dry down more than you would a Ficus. A cold, wet bougainvillea rots.","lightWinter":"Maximum light. Flowering, even indoors, depends on sun.","repotWhen":"Late spring or early summer, as heat arrives","repotCue":"Warm nights and the start of strong growth","repotMonths":[5,6,7],"repotFreq":"Every 2–3 years; they often bloom better when slightly pot-bound","repotNotes":"Very free-draining mix and a warm recovery. They dislike a big, wet pot. Do not repot in the cold months. Roots can be sparse compared with the top — be conservative if the tree looks weak.","rootPruning":"Light to moderate, only in warmth. They are not as root-tolerant as a ficus.","structuralPruning":"After a flush of bloom, or in late winter just as you prepare to ramp up water and heat. Flowers (bracts) form on new wood, so a hard prune is followed by a wait for the next flush. Thorns are real — wear gloves.","pinching":"Pinch tips after a bloom cycle to force new flowering shoots. Too much lush, nitrogen-fed growth means fewer bracts.","wiring":"Awkward because of thorns and somewhat brittle wood. Gentle wiring on younger shoots, or clip-and-grow plus ties. Protect your eyes.","fertilizing":"Light to moderate in the growing season, not heavy on nitrogen if you want color. Little or none during a cool, dry winter rest.","pests":"Aphids, caterpillars, and spider mites, especially indoors. The usual cultural complaint is no color: not enough sun, too much nitrogen or water, or not enough warmth in summer.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Simple, ovate, smooth-edged leaves, often with a sharp thorn in the axil","evergreen":true,"features":"Alternate, simple, entire, heart-to-ovate leaves. A stout thorn often sits in the leaf axil. The showy pink, magenta, red, orange, or white ‘petals’ are papery bracts around tiny true flowers. May drop leaves in a cool or dry rest. Stems are somewhat vining and irregular."},"facts":["Those vivid colors are bracts, not petals — they last much longer than typical flowers, which is why the display is so lasting.","Bougainvillea blooms most freely in heat, sun, and a slightly snug pot, with restrained feeding.","Handle with respect: the thorns are sharp, and the sap can irritate skin in some people."],"calendar":{"1":"Bright, cooler, and on the dry side. Leaf drop is not automatically a crisis. Do not keep the pot wet.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Heat and sun should bring bloom flushes. Water more as it grows, but still let the surface dry a little between waterings.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"In most of the U.S., plan the move indoors before the mid-40s°F. Inspect for pests and gradually reduce water.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"chamaecyparis-obtusa","common":"Hinoki cypress","scientific":"Chamaecyparis obtusa","synonyms":[],"aliases":["hinoki","Hinoki cypress","Japanese cypress"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Generally zones 5–8. A forest tree of Japan that likes even moisture, good air, and protection from drying wind and intense reflected heat. Many dwarf cultivars are used in bonsai.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but foliage burns in winter wind and the fine roots dry out in a small pot. Protect below about 20°F, and always give a windbreak. Not a houseplant.","dormancy":"Evergreen, with a true outdoor winter rest. Do not keep it in a heated house.","winterizing":["Leave it outside or in a bright cold frame.","Insulate the pot and, just as important, shield the foliage from drying wind and harsh winter sun.","Never overwinter in a warm indoor room."],"wateringWinter":"Water when the mix begins to dry. Evergreen sprays transpire all winter. Do not let it go bone-dry, and do not leave it in a saucer of ice water.","lightWinter":"Good light with a windbreak. A dark garage is a poor long-term home.","repotWhen":"Early spring, as growth begins","repotCue":"Just as tips start to grow, before a strong flush","repotMonths":[3,4],"repotFreq":"Every 2–3 years, watching for a broken-down or compacted mix","repotNotes":"Very free-draining but not desert-dry mix; hinoki wants moisture and oxygen together. Be conservative on roots compared with a maple. Do not bareroot a hinoki routinely. Avoid autumn repotting in the North.","rootPruning":"Moderate and careful at spring repotting. Fine roots should be preserved.","structuralPruning":"Do not cut back to bare wood with no foliage — it will not bud from nothing, like many cypresses and junipers. Thin and shorten by cutting to a tuft of foliage. Best done in spring or during the growing season, not in late fall.","pinching":"Pinch or cut tips lightly, and thin crowded sprays so the interior does not die from shade. Avoid hedge-shearing, which browns the ends and ruins the layered look.","wiring":"Younger branches are flexible; older ones can snap. Wire in autumn or early spring, with padding if needed, and do not crush the flat sprays. Check wires before they bite the thin bark.","fertilizing":"Moderate, from spring through mid-summer; taper late. They are not heavy feeders.","pests":"Spider mites in dry heat, juniper/cypress tip blights in stagnant air, and root decline from poor drainage. Heat off a south-facing wall can cook a pot.","leaf":{"group":"scale","arrangement":"opposite","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Flattened sprays of blunt, scale-like leaves","evergreen":true,"features":"Flat, ferny sprays of scale-like leaves with blunt tips (obtusa means blunt). The underside typically shows clear white stomatal markings in a ‘X’ or ‘Y’ pattern — the classic hinoki ID, and a way to separate it from juniper scale foliage, which lacks those white marks. Crushed foliage is aromatic, resinous, and pleasant. Evergreen."},"facts":["Hinoki is an important timber and temple tree in Japan, valued for its fragrant, durable wood.","The white X or Y marks on the underside of the sprays are the field mark students are taught first.","Dwarf forms such as ‘Nana Gracilis’ and ‘Chabo-yadori’ are the usual bonsai starting material."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Pinch and thin new sprays as they extend, always leaving foliage on the branch you want to keep.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"In hot regions, a little afternoon shade and careful watering prevent foliage bronzing and mites.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"taxus-cuspidata","common":"Japanese yew","scientific":"Taxus cuspidata","synonyms":[],"aliases":["Japanese yew","yew"],"family":"Taxaceae","place":"outdoor","climate":"temperate","zoneMin":"4","zoneMax":"7","zoneNote":"Generally zones 4–7. More cold-hardy than English yew (T. baccata, often 6–7). Very shade-tolerant, but as bonsai it still wants good light to stay dense. All parts except the red aril flesh are highly toxic if eaten.","rootMinF":8,"protectBelowF":18,"bringInBelowF":null,"potNote":"Hardy, but protect a shallow pot below the high teens °F and stop winter wind from burning the needles. Outdoor rest only — not a houseplant.","dormancy":"Evergreen, with a cold outdoor rest. A heated house produces weak, mite-prone growth.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot and provide a windbreak.","Do not overwinter in a warm room."],"wateringWinter":"Water when the mix begins to dry. Evergreen needles transpire in winter wind.","lightWinter":"Good light, with some shelter from the harshest midwinter sun and wind in exposed sites.","repotWhen":"Early spring, as growth begins","repotCue":"Swelling buds or the first new tips","repotMonths":[3,4],"repotFreq":"Every 2–3 years, or when the mix has broken down","repotNotes":"Well-draining mix; they will take a bit more moisture than a pine but still rot in a stagnant pot. Recovers reasonably well from spring root work. All clippings and roots are toxic — do not leave them where pets or children might chew, and wash your hands.","rootPruning":"Moderate at spring repotting.","structuralPruning":"Yews are unusually good among conifers at budding back from old wood, even fairly bare wood, which is why they are so useful in formal hedges and in bonsai renovations. Heavy cuts in spring. Wear gloves if you prefer, and never burn the trimmings in an open fire pit around food — the plant is poisonous.","pinching":"Shorten new growth in late spring and summer. Thin the interior so pads stay airy. They take regular cutting very well.","wiring":"Young branches are flexible; older yew can be stiff. Wire in autumn or early spring. The reddish or peeling bark is a design feature — protect it.","fertilizing":"Moderate, spring through mid-summer; taper late.","pests":"Scale, black vine weevil (roots and notches in needles), and mites. Winter burn is usually wind and a dry pot. Note the toxicity around pets.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Soft, flattened, single needles, dark green above, with two pale bands below","evergreen":true,"features":"Single, soft, flat needles, not in bundles and not sharp like spruce. They often look two-ranked on horizontal shoots but are actually spiral on the stem. Two pale bands on the underside; no pegs left on the twig like spruce. Female plants may bear a red, fleshy aril around a single poisonous seed. Bark on older trunks is reddish and can flake. All parts except the aril flesh are toxic."},"facts":["Yew is famous for budding back from old wood, a gift most pines and junipers do not share.","The red ‘berry’ is an aril: the fleshy part is not the main poison, but the seed inside is, and so are the leaves and wood. Treat the whole tree as poisonous if eaten.","Japanese yew handles cold better than English yew and is the usual Taxus in American bonsai collections."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"New growth is soft and easily shaped or shortened. A good month to start the year’s trimming.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch heat and drought. Many mountain conifers appreciate a little afternoon shade in hot regions. Keep watering evenly.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"picea-abies","common":"Spruce","scientific":"Picea abies","synonyms":[],"aliases":["Norway spruce","Yezo spruce","Picea jezoensis","white spruce","Picea glauca"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"2","zoneMax":"7","zoneNote":"Norway spruce (P. abies) is generally zones 2–7; white spruce (P. glauca) similar; Yezo or Ezo spruce (P. jezoensis), a classic Japanese bonsai spruce, is often listed around zones 4–6 and wants cool summers. All dislike prolonged heat and dry air. Care below is for hardy spruces as a group.","rootMinF":5,"protectBelowF":15,"bringInBelowF":null,"potNote":"Very hardy in the ground, still worth pot insulation in severe cold (around 10–15°F and below) and always worth a winter windbreak. Must stay cold — a warm garage is a bad rest.","dormancy":"Evergreen, with an obligate cold rest. Poor in mild, nearly frost-free winter climates and in hot, humid summers.","winterizing":["Leave outdoors or in a bright, truly cold frame.","Insulate the pot for deep cold and block drying wind.","Do not overwinter in a heated house or a garage that stays in the 50s°F."],"wateringWinter":"Water on mild days when the mix has started to dry. Needles desiccate in winter wind if the pot is dry.","lightWinter":"Full light and cold air.","repotWhen":"Early spring, as buds swell","repotCue":"Buds swelling, before the candles or new shoots elongate","repotMonths":[3,4],"repotFreq":"Every 2–4 years; do not disturb a happy spruce without a reason","repotNotes":"Very free-draining, gritty mix, with some moisture-holding capacity. Spruces can be sensitive about their roots — be more conservative than with a maple, keep some old soil, and work in cool spring weather, not in a hot room. Avoid autumn repotting.","rootPruning":"Conservative to moderate. Preserve fine roots and do not bareroot as a habit.","structuralPruning":"Late summer to early autumn, or carefully in spring. Spruces do not bud well from bare, needle-less wood, so never cut a branch back past the last needles if you want that branch. Design accordingly.","pinching":"In late spring, pinch or cut the new candles/shoots according to strength, often removing a portion of the extending growth before it hardens, to tighten pads. Do not shear into old, bare interior.","wiring":"Autumn through early spring. Young branches are reasonably flexible; older ones can snap, and bark is thin. The pegs (sterigmata) left by dropped needles make old twigs rough — a useful ID, and a reason to handle older pads gently.","fertilizing":"Moderate in spring and early summer; taper by late summer. Do not push a spruce into soft autumn growth.","pests":"Spider mites (very common in dry heat — rinse and inspect), adelgids, spruce budworm or sawfly in some regions, and needle casts. Heat plus drought is the usual cultural killer.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Single, usually four-sided, sharp-tipped needles set on little woody pegs","evergreen":true,"features":"Needles are single (not in fascicles), typically square or diamond-shaped in cross-section on many spruces, and sharp to the touch. Each needle sits on a tiny peg (sterigma); when the needle falls, the peg remains and the twig feels rough — a classic spruce ID versus fir or hemlock. Needles are spirally arranged. Cones hang. Yezo spruce has somewhat flatter, two-banded needles but still shows the pegs."},"facts":["If a dropped needle leaves a little peg and a rough twig, you are looking at a spruce, not a fir or a hemlock.","Yezo spruce (Picea jezoensis) is the classic bonsai spruce of Japan; Norway and white spruce are the common landscape stand-ins in North America, with very similar care.","Spruces are mountain and northern trees at heart: cool roots, good light, moist air, and a real winter."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Candle or new-shoot work as the flush extends — shorten strong shoots, leave weaker ones longer. Watch mites as soon as the weather turns dry.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"In hot regions this is the stressful month. Afternoon shade, even watering, and mite patrol matter more than styling.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"tsuga-canadensis","common":"Hemlock","scientific":"Tsuga canadensis","synonyms":[],"aliases":["Canadian hemlock","eastern hemlock","Japanese hemlock","Tsuga diversifolia"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"3","zoneMax":"7","zoneNote":"Eastern hemlock (T. canadensis) is generally zones 3–7; Japanese hemlock (T. diversifolia), a fine bonsai species, is often listed around 5–7. Both dislike heat, drought, and drying wind. In hot-summer climates they need afternoon shade and careful watering.","rootMinF":5,"protectBelowF":15,"bringInBelowF":null,"potNote":"Hardy in the ground, sensitive in a pot to winter wind and summer drought. Insulate for deep cold and always give a windbreak. Must stay cold in winter — not a houseplant.","dormancy":"Evergreen, with a cold outdoor rest. Poor in hot, windy, or drought-prone sites.","winterizing":["Keep outdoors or in a bright, cold frame, out of the worst wind.","Insulate the pot for severe cold.","Foliage burns easily in winter sun and wind if the roots are dry — check water.","Do not overwinter in a heated house."],"wateringWinter":"Do not let the pot dry out. Hemlock is less drought-tolerant than pine, even in winter.","lightWinter":"Good light with a windbreak. In summer, bright light or morning sun with afternoon shade in hot regions.","repotWhen":"Early spring, as buds swell","repotCue":"Buds swelling, before new tips extend","repotMonths":[3,4],"repotFreq":"Every 2–3 years; they have fine roots that dislike a broken-down, compacted mix","repotNotes":"Open, consistently moist but well-aerated mix. Fine roots dry quickly on the bench — keep them covered. Conservative root work. Avoid autumn repotting and avoid a hot, dry room during the job.","rootPruning":"Conservative. Preserve the fine feeding roots.","structuralPruning":"Do not cut back to bare wood; hemlock will not reliably bud from a naked branch. Cut to a tuft of foliage. The naturally drooping tips are a design feature — many growers keep a little of that grace rather than forcing a stiff outline.","pinching":"Pinch or shorten new tips in late spring as they extend. Thin crowded interior for light. Do not shear like a hedge.","wiring":"Young branches are flexible and a little droopy, which makes pad placement gentle work. Older wood snaps. Wire in autumn or early spring and protect the thin bark.","fertilizing":"Light to moderate in spring and early summer; taper early. They are not heavy feeders, and soft late growth winters poorly.","pests":"In the eastern U.S., hemlock woolly adelgid is a serious landscape pest — inspect for white woolly tufts on the undersides of needles. Also mites, scale, and drought stress. In the landscape, do not assume a collected tree is adelgid-free.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Short, flat, blunt-tipped needles, usually appearing two-ranked, with two white bands below","evergreen":true,"features":"Short (often ⅓–¾ inch), flat, soft needles with rounded or slightly notched tips, two bright white stomatal bands below, and a tiny stem (petiolule). They look two-ranked but are spirally attached. No persistent woody pegs like spruce; twigs are relatively smooth after needles drop. Leading shoots often nod or droop. Japanese hemlock (T. diversifolia) is similar, with somewhat broader, more notched needles in two ranks."},"facts":["The nodding leader and short, silvery-backed needles give hemlock a softer outline than spruce or pine.","Japanese hemlock (Tsuga diversifolia) is the species you will see in many Japanese collections; this entry covers both, with the same seasonal care.","Eastern hemlock has been devastated in parts of its native range by woolly adelgid — inspect any plant, and act early if you find it."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Pinch new tips as they extend. In hot climates, move the tree into afternoon shade before the first real heat wave.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"The dangerous month in the South and Midwest: shade, even moisture, and mite/adelgid patrol.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"cedrus-atlantica","common":"Atlas cedar","scientific":"Cedrus atlantica","synonyms":[],"aliases":["Atlas cedar","blue Atlas cedar","cedar of Lebanon","Cedrus libani","deodar","Cedrus deodara"],"family":"Pinaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"9","zoneNote":"C. atlantica is generally zones 6–9; cedar of Lebanon (C. libani) about 6–8; deodar (C. deodara) is often 7–9 and a little less hardy. All are true cedars (Cedrus), not Juniperus or Thuja. Potted trees need protection at the cold end of those ranges.","rootMinF":15,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect pots below the low 20s°F, and more carefully for deodar. They must have a cool to cold outdoor winter, not a heated house. Deodar is the most frost-tender of the three.","dormancy":"Evergreen, with a cool outdoor rest. Not indoor trees.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot before regular hard freezes, especially in zone 6.","Wind protection helps the needles.","Do not overwinter in a warm room."],"wateringWinter":"Water when the mix begins to dry. Evergreen tufts still transpire.","lightWinter":"Full light and cool to cold air.","repotWhen":"Early spring, as buds swell","repotCue":"Buds or spur tips swelling, before the new flush","repotMonths":[3,4],"repotFreq":"Every 2–4 years; they do not love frequent disturbance","repotNotes":"Very free-draining, gritty mix. Conservative root work, keeping some established soil. Spring is the conservative window. Avoid a late-autumn repot.","rootPruning":"Moderate and careful. Do not bareroot a cedar as a habit.","structuralPruning":"Do not cut back to bare wood with no needles; it will not sprout from a naked stub. Cut to a tuft of foliage. The naturally layered, horizontal pad structure (especially on Atlas and Lebanon) is a design starting point. Larger cuts in late summer or early autumn often close better than mid-winter cuts.","pinching":"Shorten new extension growth in late spring or early summer according to strength. Maintain the tufted spurs that give the tree its character. Do not shear.","wiring":"Young branches are reasonably flexible; older cedar can snap and the bark can bruise. Wire in autumn or early spring, and take bends slowly. The horizontal habit often needs more support than force.","fertilizing":"Moderate in spring and early summer; taper by late summer so the tree hardens.","pests":"Aphids, scale, bagworms, and tip or needle blights in stagnant air. Winter burn and a wet, cold pot after a late repot are cultural risks. Deodar is more often hurt by sudden hard freezes.","leaf":{"group":"needle","arrangement":"tufted","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Stiff, evergreen needles in dense rosettes of 20–40 on short spurs, and single on long shoots","evergreen":true,"features":"True cedar: evergreen needles in bottle-brush tufts or rosettes on short spurs (many needles, often 20 or more), and solitary needles on the current long shoots. Needles are usually stiffer than larch and do not drop in autumn (larch is the deciduous look-alike). Atlas cedar is often blue-green or glaucous; deodar needles are longer and softer with drooping shoot tips; cedar of Lebanon is typically greener with a more layered, table-like habit. Cones sit upright on the branches."},"facts":["If you see evergreen needle rosettes and upright cones, you have a true Cedrus, not an arborvitae or a red cedar (juniper).","Larch has similar tufts but is deciduous and turns gold in fall — a useful comparison in a mixed collection.","Blue Atlas cedar is the form most often found in American nurseries; cedar of Lebanon and deodar are used in the same way with small hardiness adjustments."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Shorten strong new extensions and keep the tufted pads open enough for light.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch heat and drought. Many mountain conifers appreciate a little afternoon shade in hot regions. Keep watering evenly.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Protection should be in place, especially for deodar in the colder parts of its range.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"cryptomeria-japonica","common":"Japanese cedar","scientific":"Cryptomeria japonica","synonyms":["Cryptomeria japonica var. sinensis"],"aliases":["sugi","Japanese cedar","cryptomeria"],"family":"Cupressaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Generally zones 5–8, sometimes 6–9 depending on the clone. Needs summer moisture and humidity, and dislikes drying wind, pollution, and a baked pot. Many dwarf cultivars are used in bonsai.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Protect pots below about 20°F and always break the winter wind. Foliage often bronzes in a hard winter, then greens again in spring — usually normal, not death. Not a houseplant.","dormancy":"Evergreen, with an outdoor cold rest. Winter bronzing of foliage is common and typically reverses.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot and provide a windbreak; winter wind and sun are what bronze and burn the sprays.","Do not overwinter in a heated house.","Keep the pot from drying out."],"wateringWinter":"Do not let it dry. Cryptomeria likes even moisture year-round, a little less in winter but never drought.","lightWinter":"Good light with a windbreak. In summer, full sun in cool climates, some afternoon shade in hot, dry ones.","repotWhen":"Early spring, as growth begins","repotCue":"Just as tips start to grow","repotMonths":[3,4],"repotFreq":"Every 2–3 years, or when the mix has compacted — they dislike a sour, tight pot","repotNotes":"An open mix that still holds moisture (they are not desert plants). Conservative to moderate root work. Keep roots from drying during the job. Avoid autumn repotting in the North.","rootPruning":"Moderate and careful at spring repotting.","structuralPruning":"Do not cut back to bare, leafless wood if you want that branch; leave foliage. Thin and shorten to a spray. Spring and summer work is safer than late fall. The naturally straight, slightly columnar habit can be designed as a formal or informal upright, or as a grove.","pinching":"Pinch or cut soft new tips and thin crowded areas so the interior does not brown. Avoid blunt shearing, which leaves brown ends.","wiring":"Young growth is flexible; older wood is brittle and the bark is relatively thin. Wire in autumn or early spring with care, and check before wires bite.","fertilizing":"Regular but not heavy in spring and early summer, with even moisture. Taper late so growth hardens. They are a bit hungrier than hinoki when growing well.","pests":"Mites in dry heat, blight in stagnant air, and root problems if the pot swings between bone-dry and waterlogged. Winter bronzing is usually cultural or seasonal, not a pest.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Awl-shaped needles, spirally arranged in five ranks, curving forward along the shoot","evergreen":true,"features":"Not a true cedar and not a flattened hinoki spray: needles are awl-shaped, pointed, and curve forward, spirally arranged all around the stem (often described as five-ranked). They feel pricklier than hinoki and lack white X/Y marks on a flat underside. Foliage may bronze in winter. Bark is reddish-brown and peels in vertical strips on older trunks. Crushed foliage is resinous."},"facts":["Sugi is the national tree of Japan and a cornerstone of Japanese forestry and temple groves.","It is often called Japanese cedar, but it is a cypress-family tree, not a Cedrus.","Winter bronzing of the needles is common and, if the tree was watered and protected, it usually greens up with spring warmth."],"calendar":{"1":"Foliage may look bronze or plum — often normal in the cold. Check water and wind protection before assuming the tree is in trouble.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"New growth extends. Begin fertilizing established, un-repotted trees, or wait 3–4 weeks after a spring repot. Protect soft new growth from a late frost and harsh wind.","5":"Pinch new tips and thin sprays. Keep water even as the weather warms.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Do not let the pot dry in a heat wave; cryptomeria is not a juniper in that respect.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Winter protection should be in place before hard freezes. Evergreens stay outside or in a cold, bright frame — not in a heated house.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"sageretia-theezans","common":"Chinese bird plum","scientific":"Sageretia theezans","synonyms":["Sageretia thea"],"aliases":["sweet plum","Chinese sweet plum","bird plum","Sageretia"],"family":"Rhamnaceae","place":"indoor","climate":"subtropical","zoneMin":"8","zoneMax":"10","zoneNote":"Often listed around zones 8–10, but potted trees are treated as tender in most of the U.S. A classic ‘indoor bonsai’ of the Chinese tradition, with fine twigs and mottled, exfoliating bark.","rootMinF":40,"protectBelowF":45,"bringInBelowF":45,"potNote":"Bring in before nights in the mid-40s°F. It may take a brief, very light chill, but a freeze or a cold, drafty window is risky. A cool, bright indoor winter is better than a hot, dry one.","dormancy":"No hard freeze dormancy. It can take a slightly cooler, brighter winter rest, and may drop some leaves if conditions change suddenly.","winterizing":["Indoors or into a cool greenhouse before mid-40s°F nights.","Bright light, even moisture, and no cold drafts.","Some leaf drop after a move is common; stabilize light and watering rather than making big changes."],"wateringWinter":"Evenly moist, never bone-dry and never soggy. It is less forgiving of a hard dry-down than a ficus.","lightWinter":"Bright light. A cool room with a strong window is ideal.","repotWhen":"Late spring or early summer","repotCue":"Warmth and active growth","repotMonths":[5,6,7],"repotFreq":"Every 1–2 years; it is often a dense rooter in a small pot","repotNotes":"Free-draining but moisture-retentive tropical or deciduous-style mix. Moderate root work in warmth. Avoid a late-autumn repot in a cold house.","rootPruning":"Moderate, in the growing season. Conservative if the tree has just dropped leaves.","structuralPruning":"During growth. It ramifies extremely well and is often styled with a very fine canopy. The mottled, flaking bark on older trunks is a feature — avoid wire scars there. Small flowers and dark berries may appear on a happy tree.","pinching":"Frequent pinching or short clipping through the growing season is how you keep the tiny internodes.","wiring":"Young twigs are fine and can be wired very gently; they mark or snap if rushed. Clip-and-grow does most of the work.","fertilizing":"Regular, light to moderate feeding in the growing season; little in winter unless it is clearly growing under strong light.","pests":"Scale, mealybugs, spider mites, and aphids. Sudden leaf drop is often a water or draft issue. Some trees are a bit fussy in very dry indoor air.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Very small, ovate, finely toothed leaves with a neat herringbone of side veins","evergreen":true,"features":"Alternate, small (often ¼–¾ inch) ovate leaves with a finely serrate margin and clearly parallel, slightly recessed side veins. Evergreen or nearly so in a mild setting. Older bark flakes in attractive gray, tan, and cream patches. Tiny flowers and small dark fruit may appear. Compare Chinese elm, which has a more lopsided leaf base and a different bark pattern, and zelkova, which is fully deciduous in a cold winter."},"facts":["A staple of Lingnan and later indoor Chinese bonsai, valued for naturally small leaves and beautiful bark.","The common names ‘sweet plum’ and ‘bird plum’ refer to the small fruit, not a relationship to Prunus.","It is sometimes labeled Sageretia thea; care is the same."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Prime month for pinching, ramification, and any needed repotting. Keep moisture even in the heat.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"podocarpus-macrophyllus","common":"Buddhist pine","scientific":"Podocarpus macrophyllus","synonyms":[],"aliases":["Buddhist pine","yew podocarpus","kusamaki","Podocarpus"],"family":"Podocarpaceae","place":"both","climate":"subtropical","zoneMin":"8","zoneMax":"10","zoneNote":"Often listed zones 8–10, sometimes 7b–11 with shelter. Landscape trees may take brief lows around 15–20°F, but a potted tree is less hardy. In most of the U.S. it is an indoor/outdoor plant. It looks like a yew or pine but is neither.","rootMinF":25,"protectBelowF":35,"bringInBelowF":35,"potNote":"A conservative plan is to protect or bring in a potted tree as nights drop toward the mid-30s°F, and not to leave it out for a hard freeze. In zone 9–10 it may stay out with pot protection. A cool, bright indoor winter is better than a dark, hot one.","dormancy":"Evergreen, without a hard freeze requirement. It will rest in short days and cool temperatures. Do not freeze it.","winterizing":["In zone 8 or colder, move to a cool, bright, frost-free place before a hard freeze — often as nights settle in the 30s°F.","In milder zones, protect the pot and cover for a rare frost.","Give good light; it is evergreen and will weaken in a dark garage.","Reduce water slightly, but do not let it dry out hard."],"wateringWinter":"When the surface begins to dry. Cooler, dimmer trees need less; do not keep them soggy.","lightWinter":"Bright light. A south or west window, or a cool greenhouse, is ideal.","repotWhen":"Late spring or early summer, when warmth is reliable","repotCue":"Active growth in warm weather","repotMonths":[5,6,7],"repotFreq":"Every 2–3 years","repotNotes":"Free-draining mix with some moisture-holding capacity. Moderate root work in warmth. Avoid a late-autumn or mid-winter repot in a cold house.","rootPruning":"Moderate, only in the growing season.","structuralPruning":"During growth. It will take cutting and, unlike many pines, can bud from older wood more obligingly, which is why it is so popular as a formal upright or as a garden topiary. Still, leaving some foliage on a branch is safer than a naked stub.","pinching":"Shorten new flushes in the growing season to keep internodes short. Thin for light into the pads.","wiring":"Young branches are fairly flexible; older wood is stiff. Wire in the growing season or early spring, and protect the bark.","fertilizing":"Regular in the growing season; light or none during a cool indoor rest.","pests":"Scale (common), sooty mold, and mites indoors. Overwatering in a cool, dark room is a typical winter problem.","leaf":{"group":"needle","arrangement":"spiral","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Long, leathery, linear-lanceolate ‘needles’ (actually leaves), with a clear midvein, not in bundles","evergreen":true,"features":"Spiral, single, strap-like leaves, typically 2–4 inches (shorter on trained bonsai), leathery, dark green, with a visible midrib, not sharp like spruce and not bundled like pine. They look like long, soft yew leaves. No milky sap. Female trees may produce a fleshy, often purplish receptacle with a seed; all parts are generally treated as not for eating. Bark becomes fibrous and interesting with age."},"facts":["It is called Buddhist pine or yew podocarpus, but it is a podocarp, not a pine and not a Taxus.","A traditional tree of Japanese and Chinese temple gardens (kusamaki), and a standard indoor bonsai in cold climates.","The long, midveined leaves that are not in fascicles are the quick way to separate it from any true pine."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"In a mild climate, growth may start; in a cold house, wait for warmth before any root work.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Best window for repotting and for serious pruning, when warmth will carry the tree.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"ilex-crenata","common":"Japanese holly","scientific":"Ilex crenata","synonyms":[],"aliases":["Japanese holly","box-leaved holly","crenate holly"],"family":"Aquifoliaceae","place":"outdoor","climate":"temperate","zoneMin":"5","zoneMax":"8","zoneNote":"Generally zones 5–8 or 6–8, depending on the cultivar. Looks like boxwood at a glance, but it is a true holly. Female plants may bear small black berries if a male is nearby.","rootMinF":10,"protectBelowF":20,"bringInBelowF":null,"potNote":"Hardy, but evergreen foliage burns in winter wind, and a shallow pot can freeze dry. Protect below about 20°F and give a windbreak. Outdoor rest — not a warm houseplant.","dormancy":"Evergreen, with a cold outdoor rest. Needs that chill; a heated room produces weak growth.","winterizing":["Keep outside or in a bright cold frame.","Insulate the pot and block winter wind and harsh sun.","Do not overwinter in a heated house.","Keep the pot from drying out."],"wateringWinter":"Water when the mix begins to dry. Evergreen leaves still transpire. They like slightly acidic, even moisture and dislike a bone-dry pot in the wind.","lightWinter":"Good light with a windbreak. In summer, full sun to light shade; some afternoon shade in hot, dry sites.","repotWhen":"Early spring, as growth begins","repotCue":"Swelling buds or the first new shoots","repotMonths":[3,4],"repotFreq":"Every 2–3 years","repotNotes":"Well-draining, slightly acidic mix. Moderate root work in spring. Avoid autumn repotting in the North. They do not want a limey, heavy soil.","rootPruning":"Moderate at spring repotting.","structuralPruning":"Takes cutting very well and back-buds on older wood better than many evergreens, similar to boxwood. Heavy cuts in spring; maintenance clipping through the growing season. Cut to a leaf rather than blunt-shearing if you want a natural look.","pinching":"Shorten new growth after it extends. Thin the interior so the tiny leaves stay healthy. It can be kept very dense.","wiring":"Young branches wire reasonably well; older wood is stiff. The fine twigs and small leaves suit formal and informal uprights and clumps. Wire in spring or autumn and check often.","fertilizing":"Moderate, from spring through mid-summer; an acid-forming feed is helpful if your water is alkaline. Taper late.","pests":"Scale, leaf miner, spider mites, and chlorosis from alkaline soil or water. Winter burn is usually wind plus a dry pot. Berries (on females) are attractive and, like many hollies, not for eating.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"crenate","shape":"Tiny, oval, glossy evergreen leaves with blunt, rounded teeth (crenate)","evergreen":true,"features":"The boxwood look-alike: very small, glossy, evergreen leaves, usually ⅓–¾ inch, but arrangement is alternate, not opposite, and the margin is crenate (blunt-toothed), not entire. No sharp holly spines. Male and female flowers are usually on separate plants; females may bear small black berries. Stems are not square like young boxwood."},"facts":["If you are not sure whether a tiny-leaved evergreen is boxwood or Japanese holly, check the arrangement: opposite on boxwood, alternate on Ilex crenata.","It is a standard hedge plant in Japan and takes pruning well enough to make a dense, refined bonsai.","Unlike English holly, the leaves are not spiny, which is why it is so pleasant to handle and to style."],"calendar":{"1":"Dormant and cold. Protect the pot and shelter foliage from drying wind and winter sun. Water when the root ball begins to dry. No fertilizer.","2":"Late dormancy. Prepare for spring repotting if the tree is root-bound. Keep winter protection in place.","3":"Main repotting window for most hardy conifers, as buds swell and before a strong flush. Use a sharp-draining mix. Do not strip all old soil from a weak tree.","4":"A good month to repot and to begin the year’s trimming as new growth starts.","5":"Pinch or cut new growth according to the species (see the care notes). Full sun or the light recommended for the species. Regular water and fertilizer.","6":"Continue shaping the new flush. Avoid heavy root work now except where a species specifically allows mid-summer work in your climate.","7":"Watch heat and drought. Many mountain conifers appreciate a little afternoon shade in hot regions. Keep watering evenly.","8":"Taper fertilizer so growth hardens. Check wires. Watch for mites in dry heat.","9":"Stop fertilizing. Light cleanup of spent foliage is fine. Do not repot in the North.","10":"A good wiring month as growth slows. Reduce water slightly. Prepare wind protection and pot insulation.","11":"Evergreen — protection and a windbreak should already be in place. Do not move it into a warm room.","12":"Check moisture on mild days. Winter burn comes from cold wind and sun on dry roots — keep the root ball from drying out."}},{"id":"conocarpus-erectus","common":"Buttonwood","scientific":"Conocarpus erectus","synonyms":[],"aliases":["buttonwood","button mangrove","silver buttonwood"],"family":"Combretaceae","place":"indoor","climate":"tropical","zoneMin":"10","zoneMax":"11","zoneNote":"A tropical coastal tree of the Caribbean and Florida. Outdoors year-round only in zones 10–11. A classic tropical bonsai, including the silver-leaved form (often called var. sericeus).","rootMinF":50,"protectBelowF":55,"bringInBelowF":55,"potNote":"Bring in before nights in the low 50s°F. No frost, and no long spells in the 40s. It likes warmth, light, and a free-draining pot.","dormancy":"No cold dormancy. Growth slows in short days. Keep it warm and bright.","winterizing":["Indoors before the low 50s°F.","Pest-check, then the brightest light you can give.","Water a little less in short days, but do not dry it out hard.","Avoid cold drafts and icy window glass."],"wateringWinter":"When the surface begins to dry. Indoor heat dries pots quickly; still, do not leave it standing in water in a cool room.","lightWinter":"Maximum light.","repotWhen":"Late spring and summer, in warmth","repotCue":"Active growth and warm nights","repotMonths":[5,6,7,8],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Very free-draining mix; in nature it is a coastal, often sandy-soil tree, and it dislikes a sour pot. Recovers well from root work in heat. Do not repot as you bring it into a dim winter room.","rootPruning":"Fairly firm in summer on a healthy tree. The spreading, often buttressed foot is a design feature — develop it at each repot.","structuralPruning":"During growth. It back-buds well and can be kept ramified. Deadwood is sometimes used, but tropical hardwoods and indoor air can make that a careful choice. Style in summer when recovery is strongest.","pinching":"Pinch or clip new shoots through the growing season to keep internodes short.","wiring":"Young branches are fairly flexible in the growing season. Older wood is hard. The bark can be interesting — avoid unnecessary scars.","fertilizing":"Regular in the growing season; light or none in a low-light winter unless it is growing under strong lights.","pests":"Scale, mealybugs, and spider mites, especially indoors. Salt is not required in a pot, despite its coastal origin; ordinary careful watering is enough.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"entire","shape":"Leathery, elliptic to ovate, smooth-edged leaves; green or silvery depending on the form","evergreen":true,"features":"Alternate, simple, entire, leathery leaves, typically 1–3 inches. The silver form is densely covered in fine gray hairs; the green form is smoother and darker. No milky sap. Small, button-like flower/fruit clusters give the tree its common name. Evergreen. Twigs are often slightly angled; older trunks can be gnarled or buttressed."},"facts":["Buttonwood is one of the signature tropical bonsai of Florida and the Caribbean, valued for rugged trunks and smallish leathery leaves.","The silver form is the same species with a dense, silky pubescence — striking in a show, and a little more sun-loving in appearance.","The ‘buttons’ are tight, cone-like flower and fruit clusters, not woody cones of a conifer."],"calendar":{"1":"Indoor or frost-free care. Give the brightest light you can, keep temperatures generally above 50–60°F, and water when the surface begins to dry. Growth may be slow; fertilize lightly or not at all if the tree is resting.","2":"Same as mid-winter. Days are still short — a south window or a grow light helps prevent weak internodes. Watch for spider mites and scale in dry indoor air.","3":"Light returns. You can resume a light fertilizer if the tree is growing. Hold off on major repotting until nights are reliably warm if the tree will go back outside.","4":"In much of the U.S. it is still too chilly at night to go outside. Continue indoor care. This can be a good indoor-pruning month if growth has started.","5":"After the last frost and once nights stay above the tree’s comfort temperature, begin hardening it off outdoors: a few hours of shade the first days, then more sun. Late spring into summer is the preferred repotting season.","6":"Peak growing season. Full sun or light shade depending on the species. Fertilize regularly. Repot and root-prune now, when warmth will power recovery. Prune and wire as it grows.","7":"Keep up water and fertilizer. High heat may call for midday shade on thinner leaves. This is still an excellent month for styling and, in warm conditions, root work.","8":"Continue summer care. Watch for pests. If you need a last repot of the year, do it early enough that roots re-establish before fall.","9":"In cool-summer regions the tree may still be in full growth; in the North, start watching night temperatures. Taper fertilizer if the tree will spend winter indoors under weaker light.","10":"For most of the U.S., plan the move indoors before nights drop into the 50s°F (or the species’ stated threshold). Inspect for pests first so you do not bring them in.","11":"Should already be in its winter home in any climate with frost. Bright light, modest water, stable temperatures, no cold drafts or heating vents. Expect some leaf drop after the move — usually temporary.","12":"Steady indoor care. Do not overwater in the short days. A cool but frost-free room with strong light is better than a dark, hot one."}},{"id":"prunus-mume","common":"Japanese apricot","scientific":"Prunus mume","synonyms":[],"aliases":["ume","Japanese flowering apricot","mume","Japanese plum"],"family":"Rosaceae","place":"outdoor","climate":"temperate","zoneMin":"6","zoneMax":"8","zoneNote":"Generally zones 6–8, sometimes listed 6–9. A beloved early-flowering Japanese fruit tree (ume). It needs a real winter chill to bloom, and open flowers can be spoiled by a hard late freeze. Related flowering cherries (Prunus serrulata and others) follow a very similar yearly rhythm, usually blooming a little later.","rootMinF":12,"protectBelowF":22,"bringInBelowF":null,"potNote":"Protect pots below the low 20s°F. Keep it cold in winter — a heated house usually costs you the bloom. When flowers open in late winter, protect them from a severe night.","dormancy":"Deciduous. Requires a cold rest and a chilling period for reliable bloom. Outdoor or cold-frame winter only.","winterizing":["Leave it outside or in a cold frame to go dormant and stay cold.","Insulate the pot before severe freezes.","Do not overwinter in a heated house.","Once buds swell and flowers open (sometimes as early as January or February in a mild spell), have a cover ready for a hard night."],"wateringWinter":"Modest; increase slightly as buds swell. Never bone-dry.","lightWinter":"Low light is fine while fully dormant. As buds move, give good light and protect open flowers from a hard freeze.","repotWhen":"After flowering, in early spring, or in late winter just as vegetative buds move if the tree has already bloomed","repotCue":"When flowers fade and leaf buds begin to swell","repotMonths":[3,4],"repotFreq":"Every 1–2 years when young; every 2–3 years when mature","repotNotes":"Free-draining deciduous mix. After-bloom spring work is the conservative standard, so you do not knock off a year’s flowers. Roots can be vigorous. Avoid autumn repotting.","rootPruning":"Moderate, after bloom or as growth starts.","structuralPruning":"Immediately after flowering. Flowers are borne on short spurs and older wood, so a late-summer or autumn hard prune removes the next winter’s display. Build a graceful, slightly informal structure, and leave a network of flowering spurs.","pinching":"Shorten long vegetative shoots after they have extended, without stripping the short spurs you want to bloom.","wiring":"After flowering or after leaf-drop. Young wood is flexible; older Prunus can be brittle and the bark (often glossy or lenticelled) marks. Many growers prefer clip-and-grow plus a little careful wire.","fertilizing":"After bloom through mid-summer, then taper. Too much nitrogen favors leafy shoots over flower buds.","pests":"Aphids, borers on stressed trunks, shot-hole or other leaf spots, and the usual Prunus fungal issues in wet springs. Good airflow and a strong, unstressed tree are the first defense. Fruit (on some trees) can be thinned if it is heavy.","leaf":{"group":"broad","arrangement":"alternate","compound":"simple","lobed":"none","lobes":"","margin":"serrate","shape":"Broadly ovate, finely toothed leaves with a long pointed tip, often with two small glands on the petiole","evergreen":false,"features":"Alternate, simple, finely serrate, ovate leaves with a tapering tip, typically 1½–3 inches. Two small glands are often visible on the petiole, a common Prunus mark. Flowers are usually pale pink or white, fragrant, and appear on bare wood in late winter — earlier than most cherries. The fruit, when present, is a small apricot-like ume, not a typical sweet cherry. Winter twigs show distinct buds on short spurs."},"facts":["Ume is one of the three friends of winter in East Asian art, celebrated for blooming on bare wood while the year is still cold.","It is an apricot, not a true plum or cherry, though it is often translated as ‘Japanese plum.’","Flowering cherries (Prunus serrulata and related species) can use this same seasonal plan; they typically bloom later, with the leaves closer behind, and their fruit and bark details differ."],"calendar":{"1":"In a mild winter, buds may already be swelling. Keep the tree cold and the pot protected, and be ready to cover open flowers on a bitter night.","2":"Peak bloom in many milder parts of the U.S., sometimes later in the North. Enjoy the flowers; delay heavy work until they fade.","3":"After flowering, prune and repot. This is the main structural window of the year.","4":"Spring flush. Water more as the tree leafs out. Wait 3–4 weeks after repotting before fertilizing. Watch for aphids on new growth. Light pinching can begin once shoots extend.","5":"Active growth. Fertilize regularly with a balanced or slightly nitrogen-forward feed. Pinch or shorten long shoots to keep internodes short. Move toward the growing placement; avoid a sudden blast of hot afternoon sun on thin-leaved trees.","6":"Continue fertilizing and pinching. On healthy, vigorous trees, partial defoliation or leaf reduction may be considered in early to mid-summer. Water faithfully — pots dry fast in heat.","7":"Heat stress is the risk. Give afternoon shade if leaves scorch, keep up watering, and do not start major root work. A mid-summer rest on fertilizer is fine during heat waves.","8":"Taper nitrogen so growth can harden for winter. You may still do light maintenance pruning. Watch for spider mites in hot, dry weather.","9":"Stop or strongly reduce fertilizer by mid to late month so the tree hardens off. Early fall is a poor time to repot in the North. Clean up, and check wires before they bite into fall thickening.","10":"Leaf-drop reveals next year’s flowering spurs. Cleanup and light wiring only — not a hard prune.","11":"Leaves should be off, or nearly so. Set up winter protection before the first hard freeze. No fertilizer. Water sparingly. A good month to study structure and apply or adjust wire on dormant wood.","12":"Mid-winter rest. Check the pot on milder days so it never goes bone-dry. Re-secure covers after wind. Do not bring a dormant hardy tree into a warm house."}}];

const SPECIES_BY_ID=Object.fromEntries(SPECIES.map(s=>[s.id,s]));
function binomial(name){
  if(!name) return "";
  const p=String(name).trim().split(/\s+/);
  return p.length>=2 ? (p[0]+" "+p[1]).toLowerCase() : String(name).trim().toLowerCase();
}
function allNames(s){
  const n=[s.scientific, ...(s.synonyms||[]), ...(s.aliases||[]), s.common];
  return n.filter(Boolean);
}
function matchSpeciesToName(scientific){
  const bin=binomial(scientific);
  if(!bin) return {kind:"none", species:null, genus:null, candidates:[]};
  const exact=SPECIES.filter(s => binomial(s.scientific)===bin || (s.synonyms||[]).some(x=>binomial(x)===bin));
  if(exact.length) return {kind:"exact", species:exact[0], genus:bin.split(" ")[0], candidates:exact};
  const genus=bin.split(" ")[0];
  const g=SPECIES.filter(s => binomial(s.scientific).split(" ")[0]===genus || (s.synonyms||[]).some(x=>binomial(x).split(" ")[0]===genus));
  if(g.length===1) return {kind:"genus-one", species:g[0], genus, candidates:g};
  if(g.length>1) return {kind:"genus", species:null, genus, candidates:g};
  return {kind:"none", species:null, genus, candidates:[]};
}
function filterByLeaf(list, filters){
  return list.filter(s=>{
    const L=s.leaf||{};
    for(const [k,v] of Object.entries(filters||{})){
      if(v===undefined || v===null || v==="") continue;
      if(k==="evergreen"){ if(Boolean(L.evergreen)!==Boolean(v)) return false; continue; }
      if(k==="deciduousNeedles"){
        if(v && !(L.group==="needle" && L.evergreen===false)) return false;
        continue;
      }
      if(String(L[k]||"")!==String(v)) return false;
    }
    return true;
  });
}
